INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.NATURA.COMPASS_DIRECTION.CD_POINTS', 'SOCI.G4.NATURA.COMPASS_DIRECTION', 'social_studies', 4, 'Name the four cardinal points, their order and their opposites', ARRAY['SOCI.G4.NATURA.COMPASS_DIRECTION.a']::text[], 'The child names north, east, south and west in order round a compass, knows north is opposite south and east is opposite west, knows that facing north east is on the right hand and west on the left, and knows the sun rises in the east and sets in the west. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the point opposite another","say which side east or west is when facing north","say where the sun rises and sets","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.NATURA.COMPASS_DIRECTION.CD_DIRECTIONS', 'SOCI.G4.NATURA.COMPASS_DIRECTION', 'social_studies', 4, 'Give directions between places on a described map', ARRAY['SOCI.G4.NATURA.COMPASS_DIRECTION.b']::text[], 'Given a map described in words or a small table, the child says the direction from one place to another, reverses it correctly and gives the direction a walker faces after a quarter turn. Map questions are in words or a small described table, and any county named on a map is an imaginary one. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say which direction one place lies from another","turn a direction round (A is north of B, so B is south of A)","say the direction after a turn","read a small table of places"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SUBCOUNTY', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE', 'social_studies', 4, 'Say what sub-counties are and how they fit inside the county', ARRAY['SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.a']::text[], 'The child knows a county is divided into sub-counties and a sub-county into wards, that a sub-county is smaller than its county, and that a neighbouring county is a different county and not one of its sub-counties. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the unit that is part of a county","put county, sub-county and ward in order of size","say whether a place is inside or outside the county","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_NEIGHBOUR_DIRECTION', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE', 'social_studies', 4, 'Locate the county in relation to its neighbouring counties', ARRAY['SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.b']::text[], 'Given a described map or table, the child says which neighbouring county lies in each direction, turns the direction round, and names only the counties that share a boundary, not those further away. Map questions are in words or a small described table, and any county named on a map is an imaginary one. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say which direction a neighbour lies from the county","name the neighbour in a given direction","say which counties share a boundary","read a small table of neighbours"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SIZE', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE', 'social_studies', 4, 'Compare the size of the county with its neighbours', ARRAY['SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.c']::text[], 'Given the areas of counties in square kilometres, the child says which is larger and about how many times, compares the whole numbers by their size and not by their first digit, and does not mix up the size of a county with the number of people in it. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say which county is larger from the areas given","say about how many times larger one is","tell size from population","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_KINDS', 'SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE', 'social_studies', 4, 'Identify the main kinds of physical feature in a county', ARRAY['SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.a']::text[], 'The child names a hill (low rounded high ground), a mountain (much higher), a valley (low land between hills or mountains), a plain (wide flat land), a river (water flowing in a channel), a lake (water with land around it) and the ocean coast from a short description. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the kind of feature from a description","pick the odd one out","tell a hill from a mountain, a river from a lake, a plain from a valley","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_IMPORTANCE', 'SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE', 'social_studies', 4, 'State how physical features help people', ARRAY['SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.b']::text[], 'The child matches rivers and lakes to water, fish and irrigation, mountains and hills to rain, forests and tourism, plains to farming and building, and the coast to fishing and ports, and does not call a feature useless or give it a use it does not have. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["match a feature to its use","say why a feature matters to the people near it","pick the false use","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_NAMES', 'SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY', 'social_studies', 4, 'Name the four seasons of the county and tell them apart', ARRAY['SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.a']::text[], 'The child names the four seasons as hot, cold, dry and rainy, matches each to its weather, knows the long rains come around March to May and the short rains around October to December, and does not use the names spring, summer, autumn and winter or call one rainy day a season. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the season from its weather","pick the season that has long or short rains","say whether a statement is about one day or a whole season","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ACTIVITIES', 'SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY', 'social_studies', 4, 'Explain how the seasons change what people do', ARRAY['SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.b']::text[], 'The child says farmers plant when the rains begin and harvest and dry crops in the dry season, that people wear warm clothes in the cold season and drink and sell cold drinks in the hot season, and that the seasons do change what people do. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the activity that suits a season","say what a farmer does in a season","say what people wear or sell in a season","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ROAD', 'SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY', 'social_studies', 4, 'Say how rainy weather affects road safety and choose safe behaviour', ARRAY['SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.c']::text[], 'The child says rain makes roads slippery, muddy and sometimes flooded and makes it harder to see, that a driver must slow down, and that a person must never cross flooded water, never run across a road, and wait in a safe place. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what rain does to a road","choose the safe thing to do near a flooded road","say what a driver should do in heavy rain","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_KINDS', 'SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME', 'social_studies', 4, 'Identify museums, monuments and cultural centres', ARRAY['SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.a']::text[], 'The child says a museum keeps and shows old objects and records, a monument is a structure built to remember a person or event, and a cultural centre shows the way of life of communities, and knows a place is historic because of its age and meaning, not because it is new or big. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the kind of place from its job","pick the place that is a historic built environment","pick the odd one out","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_IMPORTANCE', 'SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME', 'social_studies', 4, 'Explain why historic built environments matter', ARRAY['SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.b']::text[], 'The child says historic places teach history, keep a community''s identity, bring visitors and need to be cared for, and does not say they should be pulled down because they are old. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the reason a place is kept","say what people gain from visiting","say how to treat a historic place","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_WAYS', 'SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL', 'social_studies', 4, 'Identify the ways people depend on each other in a county', ARRAY['SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.a']::text[], 'The child names trade (a farmer sells to a shopkeeper), farming (farmers feed others), the hospital (health workers care for the sick) and places of worship (leaders guide people) as ways people depend on each other, and says that each side needs the other. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say who a person depends on for a need","say what a worker gives others","match a place or worker to what it gives","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_BENEFITS', 'SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL', 'social_studies', 4, 'Explain the benefits of people depending on each other', ARRAY['SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.b']::text[], 'The child says depending on each other gives us goods and services we cannot make ourselves, brings income, lets people use different skills and builds friendship, and does not say a family can supply every need alone. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the benefit of sharing work","say what happens when nobody depends on anyone","say who gains from a trade","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.PEOPLE.POPULATION_DISTRIBUTION.PD_PATTERNS', 'SOCI.G4.PEOPLE.POPULATION_DISTRIBUTION', 'social_studies', 4, 'Describe how people are spread over a county and the reasons', ARRAY['SOCI.G4.PEOPLE.POPULATION_DISTRIBUTION.a']::text[], 'The child says population distribution is how people are spread over an area, that dense means many people for the space and sparse few, and gives reasons: many people live where soil is fertile, rain is reliable, there is water, work, roads, health care and security, and few where it is very dry, steep, flooded or unsafe. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say whether an area is dense or sparse from the figures","pick the reason an area has many or few people","tell distribution from total population","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.SOCIAL.ASPECTS_OF_TRADITIONAL_C.TC_ASPECTS', 'SOCI.G4.SOCIAL.ASPECTS_OF_TRADITIONAL_C', 'social_studies', 4, 'Identify the aspects of traditional culture and sort examples into them', ARRAY['SOCI.G4.SOCIAL.ASPECTS_OF_TRADITIONAL_C.a']::text[], 'The child names the six aspects of traditional culture (dressing, food, housing, artefacts, sports and games, festivals and ceremonies), sorts everyday examples into them, knows culture is alive and not only the past, and knows communities in one county can have different traditions. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the aspect an item belongs to","match a practice to its aspect","say whether a statement about culture is true","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.SOCIAL.THE_SCHOOL.SC_VALUES', 'SOCI.G4.SOCIAL.THE_SCHOOL', 'social_studies', 4, 'Explain the values of the school from a situation', ARRAY['SOCI.G4.SOCIAL.THE_SCHOOL.b']::text[], 'Given a short school situation, the child names the value it shows (respect, honesty, responsibility, hard work, unity, cleanliness) and says why it matters, and does not treat values as the same thing as written rules or punishments. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the value a learner shows","pick the action that shows a value","say why a value matters","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_RESOURCES_ACTIVITIES', 'SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T', 'social_studies', 4, 'Identify the resources of a county and the economic activities that use them', ARRAY['SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.a', 'SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.b']::text[], 'The child names natural resources (soil, water, forests, minerals, wildlife, climate), matches them to the activities that use them (farming, fishing, mining, lumbering, tourism, trading, manufacturing) and knows an economic activity earns a living or a product, which play and rest do not. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say whether a resource is natural or made by people","match a resource to the activity that uses it","say whether an activity is economic","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_IMPORTANCE', 'SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T', 'social_studies', 4, 'Explain why economic activities matter to people and the county', ARRAY['SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.c']::text[], 'The child says economic activities give food, income, jobs, raw materials for industries and money for the county, and does not say they only help the rich or only give money. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a reason an activity matters","say what an activity gives a family","say what an activity gives the county","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_KINDS', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY', 'social_studies', 4, 'Identify industries by what they make from what', ARRAY['SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.a']::text[], 'The child says an industry makes or processes goods from raw materials (milk to packed milk, sugarcane to sugar, tea leaves to tea, maize to flour), keeps raw material and product the right way round, and does not call a shop or a farm an industry. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the raw material or the product","say what an industry does to a raw material","say whether a place is an industry","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_BENEFITS', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY', 'social_studies', 4, 'Explain the benefits of industries in a county', ARRAY['SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.b', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.d']::text[], 'The child says industries give jobs, income, a market for farmers, goods to buy and money for the county, and says the benefits reach workers, farmers and shoppers, not only the owner. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a benefit of an industry","say who gains from a factory","say what happens to farmers near a factory","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_LOCATE', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY', 'social_studies', 4, 'Say where in a county an industry is best placed', ARRAY['SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.c']::text[], 'Given a described map or table, the child places an industry near its raw material, workers, roads and water and reads where an industry is from the table. Map questions are in words or a small described table, and any county named on a map is an imaginary one. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the best place for an industry","read where an industry is from a small table","say why an industry is near its raw material or market","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_PROJECTS', 'SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC', 'social_studies', 4, 'Choose enterprise projects a school can start', ARRAY['SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.a']::text[], 'The child names school projects (kitchen garden, poultry, tree nursery, bee-keeping, making liquid soap, recycling), chooses the one that suits the land, water and people the school has, and knows a project needs a plan. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the project that suits the school''s resources","say what a project needs before it starts","say what a project earns or gives","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_ETHICS', 'SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC', 'social_studies', 4, 'Say what honest and shared work means in a school project', ARRAY['SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.c']::text[], 'The child says project money is kept honestly and recorded, the team shares the work and decisions, mistakes are reported, and profit belongs to the project and school, not to one person. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the honest action with project money","say how the team should work","say what to do with a mistake or a loss","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.CITIZE.GOOD_CITIZENSHIP_IN_SCHO.GC_QUALITIES', 'SOCI.G4.CITIZE.GOOD_CITIZENSHIP_IN_SCHO', 'social_studies', 4, 'Identify the qualities of a good citizen in school', ARRAY['SOCI.G4.CITIZE.GOOD_CITIZENSHIP_IN_SCHO.a']::text[], 'The child names the qualities of a good school citizen (respect, honesty, responsibility, obedience to fair rules, helping others, keeping the school clean, being on time, caring for property) and does not say that only the top learners or those who never speak are good citizens. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the quality in a situation","pick the action of a good citizen","say whether a statement about good citizens is true","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.CITIZE.PEACE.PE_FACTORS', 'SOCI.G4.CITIZE.PEACE', 'social_studies', 4, 'Identify the things that promote peace in school', ARRAY['SOCI.G4.CITIZE.PEACE.a']::text[], 'The child says respect, sharing, honesty, listening, fairness, forgiveness and accepting differences promote peace, and that peace means disagreements are settled without hurting anyone, not that nobody ever disagrees. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick what promotes peace","pick what breaks peace","say what peace means","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.CITIZE.PEACE.PE_STRATEGIES', 'SOCI.G4.CITIZE.PEACE', 'social_studies', 4, 'Choose ways of settling a quarrel peacefully', ARRAY['SOCI.G4.CITIZE.PEACE.b']::text[], 'The child chooses to stay calm, listen, talk it through, say sorry and forgive, and to ask a teacher or peer mediator for help, and does not choose to fight back, take revenge or gossip. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the peaceful way to react","put the steps of settling a quarrel in order","say who can help","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.CITIZE.CHILD_RIGHTS.CR_FORMS', 'SOCI.G4.CITIZE.CHILD_RIGHTS', 'social_studies', 4, 'Outline the forms of child abuse in the community', ARRAY['SOCI.G4.CITIZE.CHILD_RIGHTS.a']::text[], 'The child names early and forced marriage, female genital mutilation, slavery, child trafficking, child and forced labour, sexual abuse, abuse of children with special needs and unsafe unauthorised school transport as child abuse, knows that beating and neglect also harm, and knows that light chores at home are not child labour. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the example that is child abuse","pick the example that is not child abuse","say whether a chore is child labour","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.CITIZE.CHILD_RIGHTS.CR_CAUSES', 'SOCI.G4.CITIZE.CHILD_RIGHTS', 'social_studies', 4, 'Explain the causes of child abuse', ARRAY['SOCI.G4.CITIZE.CHILD_RIGHTS.b']::text[], 'The child gives causes such as poverty, ignorance, harmful customs, greed, war and the harmful use of alcohol and drugs by adults, and says abuse is never the child''s fault and a custom does not make it right. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a cause of child abuse","say who is responsible","say whether a custom is a good reason","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.CITIZE.CHILD_RIGHTS.CR_EFFECTS', 'SOCI.G4.CITIZE.CHILD_RIGHTS', 'social_studies', 4, 'Explain the effects of child abuse and where a child can get help', ARRAY['SOCI.G4.CITIZE.CHILD_RIGHTS.c', 'SOCI.G4.CITIZE.CHILD_RIGHTS.d']::text[], 'The child names effects (injury, fear, sadness, dropping out of school, poor health), says a child who is hurt or whose friend is hurt must tell a trusted adult such as a teacher, parent or the Childline helpline on 116, and says harm is not kept secret. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick an effect of child abuse","say what a child should do who is being hurt","say what a child should do when a friend is hurt","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_PROCESSES', 'SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL', 'social_studies', 4, 'Identify democratic processes in school', ARRAY['SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.a']::text[], 'The child says democratic processes in school include electing prefects by a secret vote, class meetings, debates and suggestion boxes, puts the election steps in order (nomination, campaign, voting, counting, announcing) and knows a teacher appointing someone is not an election. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the democratic way to choose","put the steps of a school election in order","say whether a way of choosing is democratic","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_BENEFITS', 'SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL', 'social_studies', 4, 'Explain the benefits of democracy in school', ARRAY['SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.b']::text[], 'The child says democracy gives everyone a voice, is fair, builds peace, and makes decisions that most learners accept, and that the choice of the majority is followed while the views of the others are still respected. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a benefit of democracy","say what the majority and the minority each get","say why everyone should vote","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_COMPOSITION', 'SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN', 'social_studies', 4, 'Say who is in the Children''s Government and how they are chosen', ARRAY['SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.a']::text[], 'The child says the Children''s Government is made up of learners elected by their classmates, with a leader and ministers or prefects for different areas, guided by a patron teacher, and not by teachers alone. Posts and names vary by school. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick who belongs to the Children''s Government","say how members are chosen","say who guides the learners","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_FUNCTIONS', 'SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN', 'social_studies', 4, 'Describe what the Children''s Government does', ARRAY['SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.b']::text[], 'The child says the Children''s Government speaks for learners, helps keep order and cleanliness, organises school activities and passes learners'' worries to the teachers, and does not punish learners or run the school in place of the head teacher. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a duty of the Children''s Government","pick what it does not do","say who a learner takes a worry to","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_LEADERS', 'SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP', 'social_studies', 4, 'Identify leaders in the community and their duties', ARRAY['SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.a', 'SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.b']::text[], 'The child names religious leaders (guide people in faith and counsel), clan leaders and village elders (settle disputes and guard customs) and the chief (keeps law and order and links the village to the government), and does not say that leaders are only politicians. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the leader from a duty","say what a leader does","pick the odd one out","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_QUALITIES', 'SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP', 'social_studies', 4, 'Choose the qualities of a good leader in the community', ARRAY['SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.c', 'SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.d']::text[], 'The child says a good leader is honest, fair, listens, serves everyone and sets an example, and does not say a leader is good because he or she is the strongest, the richest or the loudest. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the quality of a good leader","say how a good leader acts in a situation","say why leaders must be honest","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_STRUCTURE', 'SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I', 'social_studies', 4, 'Identify the structure of the county government', ARRAY['SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.a']::text[], 'The child says a county government has a county executive (the Governor, the Deputy Governor and the county executive committee members) and a county assembly (the Members of the County Assembly and the Speaker), and does not mix it up with the President and Members of Parliament. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick who is in the county executive","pick who is in the county assembly","tell county government from national government","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_GOVERNOR', 'SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I', 'social_studies', 4, 'Explain the duties of the County Governor', ARRAY['SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.b']::text[], 'The child says the Governor is elected by the people of the county for five years, heads the county executive, sees that county laws are carried out, appoints the county executive committee with the assembly''s approval and reports on the county, and does not make laws or head the country. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a duty of the Governor","pick what the Governor does not do","say who elects the Governor","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_MCA', 'SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I', 'social_studies', 4, 'Explain the roles of a Member of the County Assembly', ARRAY['SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.c']::text[], 'The child says a Member of the County Assembly (MCA) is elected by a ward, makes county laws, approves the county budget, checks the work of the executive and speaks for the people of the ward, and does not carry out the laws or speak for the whole country. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a duty of the MCA","say whom an MCA represents","pick what an MCA does not do","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.COMPASS_DIRECTION.CD_POINTS', 'ENVI.G1.NATURA.WEATHER_AND_THE_SKY.a', 'outcome', 'essential', 'Watching where the sun is in the morning and evening (Grade 1) is how the child finds east and west. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.COMPASS_DIRECTION.CD_POINTS', 'MATH.G4.GEOMET.POSITION_AND_DIRECTION.TURN_FRACTIONS', 'skill', 'helpful', 'North, east, south and west are each a quarter turn apart; the child needs quarter and half turns. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.COMPASS_DIRECTION.CD_DIRECTIONS', 'SOCI.G4.NATURA.COMPASS_DIRECTION.CD_POINTS', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.COMPASS_DIRECTION.CD_DIRECTIONS', 'ENVI.G1.SOCIAL.OUR_SCHOOL.a', 'outcome', 'essential', 'Naming features between home and school (Grade 1) is the first map of real places the child gives directions on. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SUBCOUNTY', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.a', 'outcome', 'essential', 'Knowing the community around home (Grade 3) is the smallest piece the child fits inside a ward and a sub-county. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SUBCOUNTY', 'ENVI.G2.SOCIAL.OUR_MARKET.b', 'outcome', 'helpful', 'Locating the local market (Grade 2) is the child''s first sense that places sit inside a bigger area. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_NEIGHBOUR_DIRECTION', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SUBCOUNTY', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_NEIGHBOUR_DIRECTION', 'SOCI.G4.NATURA.COMPASS_DIRECTION.CD_DIRECTIONS', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_NEIGHBOUR_DIRECTION', 'ENVI.G2.SOCIAL.OUR_MARKET.a', 'outcome', 'helpful', 'Using features on the way to the market (Grade 2) is the first time the child says where one place is from another. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SIZE', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_NEIGHBOUR_DIRECTION', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SIZE', 'MATH.G4.NUMBER.WHOLE_NUMBERS.ORDER_1000', 'skill', 'essential', 'Comparing county areas means ordering whole numbers by their size, not their first digit. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_KINDS', 'ENVI.G1.SOCIAL.OUR_SCHOOL.a', 'outcome', 'essential', 'Grade 1 named the features between home and school; Grade 4 sorts them into kinds. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_KINDS', 'ENVI.G2.SOCIAL.OUR_MARKET.a', 'outcome', 'helpful', 'Naming features on the way to market (Grade 2) gives the child real hills and rivers to sort. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_IMPORTANCE', 'SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_KINDS', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_IMPORTANCE', 'ENVI.G1.RESOUR.WATER.a', 'outcome', 'essential', 'Knowing sources of water (Grade 1) is the root of "rivers and lakes give water". Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_NAMES', 'ENVI.G3.NATURA.WEATHER.a', 'outcome', 'essential', 'Grade 3 Environmental Activities taught the idea first. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_NAMES', 'ENVI.G2.NATURA.WEATHER.a', 'outcome', 'essential', 'Telling the weather at different times of day (Grade 2) comes before seeing a season as many weeks of weather. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
