INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ACTIVITIES', 'ENVI.G3.NATURA.WEATHER.c', 'outcome', 'essential', 'Responding to bad weather (Grade 3) is the child''s first link between weather and what people do. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
