INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ROAD', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.c', 'outcome', 'essential', 'Grade 3 Environmental Activities taught the idea first. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ROAD', 'ENVI.G3.NATURA.WEATHER.b', 'outcome', 'helpful', 'The dangers of bad weather (Grade 3) lead straight into rain on roads. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_KINDS', 'ENVI.G3.SOCIAL.CULTURAL_EVENTS.a', 'outcome', 'essential', 'Grade 3 Environmental Activities taught the idea first. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_KINDS', 'ENVI.G3.SOCIAL.CULTURAL_EVENTS.b', 'outcome', 'helpful', 'Seeing that cultural events keep a community together (Grade 3) is the root of why places that keep culture matter. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
