INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_MCA', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SUBCOUNTY', 'skill', 'essential', 'An MCA is elected by one ward; the child must know what a ward is. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.COMPASS_DIRECTION.CD_POINTS.M_CD_OPPOSITE', 'SOCI.G4.NATURA.COMPASS_DIRECTION.CD_POINTS', 'Gives the wrong opposite (thinks the opposite of north is east or west).', '{"question":"Which point is opposite north on a compass?","wrong_answer":"East","correct_answer":"South"}'::jsonb, 'The child reads the four points as a list, not as two straight lines crossing.', 'Offer "East" next to the right answer and ask the question again in a new context.', 'Draw a plus sign: north at the top, south at the bottom, east and west across. Ask for the point straight across.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.COMPASS_DIRECTION.CD_POINTS.M_CD_LEFT_RIGHT', 'SOCI.G4.NATURA.COMPASS_DIRECTION.CD_POINTS', 'Swaps east and west (thinks that facing north, east is on the left).', '{"question":"You face north. Which side is east on?","wrong_answer":"The left hand","correct_answer":"The right hand"}'::jsonb, 'The child pictures the compass on a page instead of standing in it.', 'Offer "The left hand" next to the right answer and ask the question again in a new context.', 'Have the child stand and face north, stretch out the right arm and say "east". Then turn and do it again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.COMPASS_DIRECTION.CD_POINTS.M_CD_SUN', 'SOCI.G4.NATURA.COMPASS_DIRECTION.CD_POINTS', 'Thinks the sun rises in the west and sets in the east, or rises in the north.', '{"question":"In which direction does the sun rise?","wrong_answer":"The west","correct_answer":"The east"}'::jsonb, 'The child remembers the sun being high or low but not the side.', 'Offer "The west" next to the right answer and ask the question again in a new context.', 'Watch the sun rise on a school morning and name the side; use it to find east and then the other points.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.COMPASS_DIRECTION.CD_DIRECTIONS.M_CD_REVERSE', 'SOCI.G4.NATURA.COMPASS_DIRECTION.CD_DIRECTIONS', 'Gives the direction the wrong way round (school is north of the market, so says the market is north of the school).', '{"question":"A school is north of a market. In which direction is the market from the school?","wrong_answer":"North","correct_answer":"South"}'::jsonb, 'The child repeats the word in the sentence and does not turn round to the other place.', 'Offer "North" next to the right answer and ask the question again in a new context.', 'Put two objects on the desk. Ask "from this one to that one", then swap and ask again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.COMPASS_DIRECTION.CD_DIRECTIONS.M_CD_TURN', 'SOCI.G4.NATURA.COMPASS_DIRECTION.CD_DIRECTIONS', 'Gets the direction wrong after a turn (facing east and turning left gives south).', '{"question":"Wanjiku faces east and turns left. Which direction does she face now?","wrong_answer":"South","correct_answer":"North"}'::jsonb, 'The child turns the wrong way or does not picture facing the direction.', 'Offer "South" next to the right answer and ask the question again in a new context.', 'Have the child stand and face a wall called east, then turn a quarter turn left and name the new wall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.COMPASS_DIRECTION.CD_POINTS.M_CD_UP_NORTH', 'SOCI.G4.NATURA.COMPASS_DIRECTION.CD_POINTS', 'Thinks north means "up" in the sky or uphill, so points at the ceiling or up a slope when asked to face north.', '{"question":"Stand up and face north. Where do you point?","wrong_answer":"Up at the sky","correct_answer":"Along the ground, to the left of the morning sun"}'::jsonb, 'Maps hang on the wall with north at the top, so the child reads "top of the map" as "up".', 'Offer "Up at the sky" next to the right answer and ask the question again in a new context.', 'Lay the map flat on the desk, then on the floor, and turn it so north on the map points along the ground to north.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.COMPASS_DIRECTION.CD_DIRECTIONS.M_CD_TOP_ALWAYS_NORTH', 'SOCI.G4.NATURA.COMPASS_DIRECTION.CD_DIRECTIONS', 'Reads "north" as the top of whatever is drawn, even when the map shows a north arrow pointing another way.', '{"question":"On a map the north arrow points to the right. The well is on the right of the school. Where is the well from the school?","wrong_answer":"East, because the right is east","correct_answer":"North, because the arrow shows north is on the right"}'::jsonb, 'Most maps in class have north at the top, so the child never looks at the arrow.', 'Offer "East, because the right is east" next to the right answer and ask the question again in a new context.', 'Draw the same village twice, once with the arrow up and once with the arrow to the right, and ask each time where north is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.COMPASS_DIRECTION.CD_DIRECTIONS.M_CD_LEFT_IS_WEST', 'SOCI.G4.NATURA.COMPASS_DIRECTION.CD_DIRECTIONS', 'Says "left" means west whichever way the person faces.', '{"question":"Achieng faces south. She turns her head to her left. Which direction is she looking?","wrong_answer":"West","correct_answer":"East"}'::jsonb, 'The child learnt "facing north, west is on the left" and uses it for every way of facing.', 'Offer "West" next to the right answer and ask the question again in a new context.', 'Stand facing south with the class and point: the left hand now points east. Turn and do it for each direction.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SUBCOUNTY.M_LS_SUB_BIGGER', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SUBCOUNTY', 'Thinks a sub-county is bigger than a county.', '{"question":"Which is bigger, a county or a sub-county?","wrong_answer":"A sub-county","correct_answer":"A county"}'::jsonb, 'The child knows both names and not which holds the other.', 'Offer "A sub-county" next to the right answer and ask the question again in a new context.', 'Use boxes inside boxes: the county box holds several sub-county boxes, which hold wards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SUBCOUNTY.M_LS_ORDER', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SUBCOUNTY', 'Puts county, sub-county and ward in the wrong order of size.', '{"question":"Which is the smallest unit: county, sub-county or ward?","wrong_answer":"Sub-county","correct_answer":"Ward"}'::jsonb, 'The child has heard the three words but not learned how they nest.', 'Offer "Sub-county" next to the right answer and ask the question again in a new context.', 'Draw the three nested boxes and label them from the outside in; then ask for smallest and largest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SUBCOUNTY.M_LS_NEIGHBOUR_SUB', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SUBCOUNTY', 'Thinks a neighbouring county is a sub-county of the learner''s own county.', '{"question":"Kalia County has a neighbour called Mwangaza County. Is Mwangaza one of the sub-counties of Kalia?","wrong_answer":"Yes, it is a sub-county of Kalia","correct_answer":"No, it is a separate county next to Kalia"}'::jsonb, 'The child treats everything nearby as inside the home county.', 'Offer "Yes, it is a sub-county of Kalia" next to the right answer and ask the question again in a new context.', 'Draw two county boxes side by side and a boundary line between them; sub-counties are drawn inside one box only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_NEIGHBOUR_DIRECTION.M_LS_DIR_REVERSE', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_NEIGHBOUR_DIRECTION', 'Reverses the direction of a neighbour.', '{"question":"On a map, Kitale County lies north of Meru County. In which direction is Meru County from Kitale County?","wrong_answer":"North","correct_answer":"South"}'::jsonb, 'The child repeats the word in the sentence and does not turn round.', 'Offer "North" next to the right answer and ask the question again in a new context.', 'Mark two dots on paper and ask the direction from each dot to the other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_NEIGHBOUR_DIRECTION.M_LS_NOT_TOUCHING', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_NEIGHBOUR_DIRECTION', 'Calls a county a neighbour when it does not share a boundary with the county.', '{"question":"Which county is a neighbour of Kalia County, with a shared boundary?","wrong_answer":"A county two counties away","correct_answer":"The county whose boundary touches Kalia"}'::jsonb, 'The child thinks near means next to.', 'Offer "A county two counties away" next to the right answer and ask the question again in a new context.', 'Use a described map: trace the boundary of the county and name only the counties that touch it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SIZE.M_LS_POP_SIZE', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SIZE', 'Thinks the county with more people is the bigger county.', '{"question":"County A has 3,000 square kilometres and 900,000 people. County B has 12,000 square kilometres and 400,000 people. Which county is larger in size?","wrong_answer":"County A, because it has more people","correct_answer":"County B, because its area is larger"}'::jsonb, 'The child mixes up how big a place is with how many people live there.', 'Offer "County A, because it has more people" next to the right answer and ask the question again in a new context.', 'Compare a large empty field and a small crowded classroom: which has more space and which has more people?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SIZE.M_LS_DIGIT', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SIZE', 'Compares numbers by their first digit instead of their size (thinks 800 is more than 3,000 because 8 is more than 3).', '{"question":"County A is 800 square kilometres and County B is 3,000 square kilometres. Which is larger?","wrong_answer":"County A","correct_answer":"County B"}'::jsonb, 'The child looks at the first digit and not at the number of digits.', 'Offer "County A" next to the right answer and ask the question again in a new context.', 'Write the two numbers in a place value table and compare the thousands first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SUBCOUNTY.M_LS_WARD_COUNTY', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SUBCOUNTY', 'Thinks the ward is the same as the county because both elect someone (an MCA and a Governor).', '{"question":"Which is smaller: a ward or a county?","wrong_answer":"They are the same size","correct_answer":"A ward; many wards make a sub-county and many sub-counties make a county"}'::jsonb, 'The child links each area to a leader and sees two leaders as two equal places.', 'Offer "They are the same size" next to the right answer and ask the question again in a new context.', 'Fit the puzzle: wards into a sub-county, sub-counties into the county, and count the pieces.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_NEIGHBOUR_DIRECTION.M_LS_INSIDE_NEIGHBOUR', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_NEIGHBOUR_DIRECTION', 'Thinks a town inside the county is a neighbouring county.', '{"question":"Kibo Town is inside Mlima County. Is Kibo Town a neighbour county of Mlima?","wrong_answer":"Yes, it is close by","correct_answer":"No, it is inside Mlima County, not beside it"}'::jsonb, 'The child uses "near" as the test of a neighbour, and a town inside is very near.', 'Offer "Yes, it is close by" next to the right answer and ask the question again in a new context.', 'On the cut-out map, put a dot for the town inside the county and colour the counties that share the edge.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_NEIGHBOUR_DIRECTION.M_LS_ONE_NEIGHBOUR_PER_SIDE', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_NEIGHBOUR_DIRECTION', 'Thinks a county can have only one neighbour in each direction.', '{"question":"Two counties both lie to the north of Mlima County and touch it. How many northern neighbours does Mlima have?","wrong_answer":"One; only one county can be north","correct_answer":"Two"}'::jsonb, 'Simple maps in class show one neighbour on each side, like a cross.', 'Offer "One; only one county can be north" next to the right answer and ask the question again in a new context.', 'Draw a county with two counties along its northern edge and count them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SIZE.M_LS_LOOKS_BIGGER', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SIZE', 'Judges size by how big a county looks on two maps of different scales.', '{"question":"Map A shows Ziwa County large on a full page. Map B shows Mlima County small in a corner. The table says Ziwa is 2,000 square kilometres and Mlima 6,000. Which is bigger?","wrong_answer":"Ziwa, it looks bigger","correct_answer":"Mlima, 6,000 is more than 2,000 square kilometres"}'::jsonb, 'The child trusts the picture and does not know two maps can be drawn to different sizes.', 'Offer "Ziwa, it looks bigger" next to the right answer and ask the question again in a new context.', 'Draw the same classroom on a big sheet and on a small card: the room did not change size.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SIZE.M_LS_UNIT_IGNORED', 'SOCI.G4.NATURA.LOCATION_AND_SIZE_OF_THE.LS_SIZE', 'Compares the numbers and ignores the units, so 3 thousand square kilometres looks smaller than 900.', '{"question":"Ziwa County is 3 thousand square kilometres. Mlima is 900 square kilometres. Which is bigger?","wrong_answer":"Mlima, 900 is more than 3","correct_answer":"Ziwa, 3 thousand is 3,000, which is more than 900"}'::jsonb, 'The child reads the digit and skips the word "thousand".', 'Offer "Mlima, 900 is more than 3" next to the right answer and ask the question again in a new context.', 'Write both as full numbers, 3,000 and 900, and line up the digits by place value.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_KINDS.M_PH_HILL_MOUNTAIN', 'SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_KINDS', 'Thinks a hill and a mountain are the same or a hill is higher.', '{"question":"Which is higher, a hill or a mountain?","wrong_answer":"A hill","correct_answer":"A mountain"}'::jsonb, 'The child uses the two words for any raised ground.', 'Offer "A hill" next to the right answer and ask the question again in a new context.', 'Compare Mount Kenya with a small hill near school: describe the height of each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_KINDS.M_PH_RIVER_LAKE', 'SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_KINDS', 'Mixes up a river and a lake.', '{"question":"Which one is water that flows along in a channel?","wrong_answer":"A lake","correct_answer":"A river"}'::jsonb, 'The child knows both have water.', 'Offer "A lake" next to the right answer and ask the question again in a new context.', 'Ask: does the water stay in one place or move on to the sea or a lake?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_KINDS.M_PH_PLAIN_VALLEY', 'SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_KINDS', 'Mixes up a plain and a valley (thinks a valley is wide flat land).', '{"question":"Which is wide flat land?","wrong_answer":"A valley","correct_answer":"A plain"}'::jsonb, 'The child thinks low land is flat land.', 'Offer "A valley" next to the right answer and ask the question again in a new context.', 'Show a bowl and a flat table: a valley lies between high land on both sides, a plain is wide and flat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_IMPORTANCE.M_PH_NO_USE', 'SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_IMPORTANCE', 'Thinks physical features have no use for people (only beautiful).', '{"question":"Why is a river important to people near it?","wrong_answer":"It is only nice to look at","correct_answer":"It gives water for drinking, farming and fish"}'::jsonb, 'The child sees the features as scenery.', 'Offer "It is only nice to look at" next to the right answer and ask the question again in a new context.', 'Ask each learner to name one thing in the day that comes from water or land near home.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_IMPORTANCE.M_PH_WRONG_USE', 'SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_IMPORTANCE', 'Matches a feature to a use it does not have (farming on a lake, fishing on a plain).', '{"question":"Which feature is best for fishing?","wrong_answer":"A plain","correct_answer":"A lake"}'::jsonb, 'The child guesses from the word and not from what the feature is.', 'Offer "A plain" next to the right answer and ask the question again in a new context.', 'Match each feature to what it is made of: water, high ground, flat land. Then ask what each can give.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_IMPORTANCE.M_PH_HARM_ONLY', 'SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_IMPORTANCE', 'Thinks mountains and valleys only get in the way and do no good.', '{"question":"How does a mountain help people?","wrong_answer":"It only blocks the road","correct_answer":"It brings rain, rivers and visitors"}'::jsonb, 'The child sees only the difficulty of travelling over a mountain.', 'Offer "It only blocks the road" next to the right answer and ask the question again in a new context.', 'Trace a river from its source on a mountain to the farms below.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_KINDS.M_PH_MAN_MADE_FEATURE', 'SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_KINDS', 'Counts a dam, a road or a building as a physical feature.', '{"question":"Which of these is a physical feature: a hill, a road, a school?","wrong_answer":"A road","correct_answer":"A hill"}'::jsonb, 'The child takes "physical" to mean anything you can see and touch.', 'Offer "A road" next to the right answer and ask the question again in a new context.', 'Sort pictures into "made by nature" and "made by people": only nature''s go in the physical features box.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_IMPORTANCE.M_PH_SWAMP_USELESS', 'SOCI.G4.NATURA.PHYSICAL_FEATURES_IN_THE.PH_IMPORTANCE', 'Thinks a swamp or wetland is only a dirty, useless place to be drained.', '{"question":"What is a swamp good for?","wrong_answer":"Nothing; it should be filled in","correct_answer":"It holds water, gives papyrus and reeds and is home to fish and birds"}'::jsonb, 'The child knows swamps as muddy places with mosquitoes and has never seen what they give.', 'Offer "Nothing; it should be filled in" next to the right answer and ask the question again in a new context.', 'Show papyrus mats or baskets and ask where the papyrus grows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_NAMES.M_SE_FOREIGN_NAMES', 'SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_NAMES', 'Uses spring, summer, autumn and winter as the seasons of the county.', '{"question":"Which of these is a season in our county?","wrong_answer":"Autumn","correct_answer":"The rainy season"}'::jsonb, 'The child has met the four names in picture books from other lands.', 'Offer "Autumn" next to the right answer and ask the question again in a new context.', 'Ask the child to name the weather of each month of the school year, then give each stretch its own name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_NAMES.M_SE_COLD_RAIN', 'SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_NAMES', 'Mixes up the seasons (thinks the rainy season is the hot season, or cold means rain).', '{"question":"When there is little rain and no clouds for many days, which season is it?","wrong_answer":"The rainy season","correct_answer":"The dry season"}'::jsonb, 'The child names a season by one feature and not by the whole.', 'Offer "The rainy season" next to the right answer and ask the question again in a new context.', 'Make a weather chart over a week and name the season from what it shows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_NAMES.M_SE_DAY_SEASON', 'SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_NAMES', 'Treats one day of weather as a whole season.', '{"question":"It rained on Tuesday. What can we say?","wrong_answer":"It is now the rainy season","correct_answer":"It rained that day, and a season lasts for many weeks"}'::jsonb, 'The child does not tell weather of a day from a season.', 'Offer "It is now the rainy season" next to the right answer and ask the question again in a new context.', 'Ask what the weather was every day of one month, then name the season.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ACTIVITIES.M_SE_PLANT_DRY', 'SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ACTIVITIES', 'Thinks farmers should plant when the ground is dry.', '{"question":"When do farmers plant maize?","wrong_answer":"In the dry season","correct_answer":"When the rains begin"}'::jsonb, 'The child does not link the seeds to the need for water.', 'Offer "In the dry season" next to the right answer and ask the question again in a new context.', 'Plant two cups of beans, water one, and compare after a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ACTIVITIES.M_SE_ACT_MISMATCH', 'SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ACTIVITIES', 'Matches a season to an activity that does not fit it (warm sweaters in the hot season).', '{"question":"What do people wear in the cold season?","wrong_answer":"Light cotton shirts only","correct_answer":"Warm clothes such as sweaters"}'::jsonb, 'The child does not think of the weather of the season.', 'Offer "Light cotton shirts only" next to the right answer and ask the question again in a new context.', 'Ask what the child wears on a cold morning and what on a hot afternoon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ACTIVITIES.M_SE_NO_EFFECT', 'SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ACTIVITIES', 'Thinks seasons make no difference to what people do.', '{"question":"Do seasons change what people do?","wrong_answer":"No, people do the same all year","correct_answer":"Yes, farmers, traders and travellers change what they do"}'::jsonb, 'The child lives in a town and does not see farming.', 'Offer "No, people do the same all year" next to the right answer and ask the question again in a new context.', 'Ask what changes at home when the rains start: crops, roads, clothes, school trips.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ROAD.M_SE_RUN_ACROSS', 'SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ROAD', 'Thinks it is safe to run across a wet road to get out of the rain.', '{"question":"It is raining. What should Njeri do at the road?","wrong_answer":"Run across fast to get out of the rain","correct_answer":"Wait at the side and cross only when the road is clear"}'::jsonb, 'The child thinks of being dry, not of slippery roads and poor sight.', 'Offer "Run across fast to get out of the rain" next to the right answer and ask the question again in a new context.', 'Role play crossing in the rain: slow, look both ways, hold a friend''s hand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ROAD.M_SE_FLOOD_CROSS', 'SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ROAD', 'Thinks it is safe to cross flooded water if it looks shallow.', '{"question":"A road has water flowing across it after heavy rain. What should you do?","wrong_answer":"Cross if the water looks shallow","correct_answer":"Do not cross: go back and tell an adult"}'::jsonb, 'The child cannot judge how deep or how fast water is.', 'Offer "Cross if the water looks shallow" next to the right answer and ask the question again in a new context.', 'Show a picture of a drift in flood; ask what is hidden under the water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ROAD.M_SE_RAIN_SAFER', 'SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ROAD', 'Thinks rain makes the road safer or that drivers should speed up to get out of the rain.', '{"question":"How should a driver drive in heavy rain?","wrong_answer":"Faster, to get out of the rain","correct_answer":"Slowly, because the road is slippery and it is hard to see"}'::jsonb, 'The child links getting home sooner with safety.', 'Offer "Faster, to get out of the rain" next to the right answer and ask the question again in a new context.', 'Ask how long it takes to stop on a slippery floor when you run.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_NAMES.M_SE_SAME_EVERYWHERE', 'SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_NAMES', 'Thinks every county has its rains in the same months and the same seasons as their own.', '{"question":"Is the rainy season in the same months in every part of Kenya?","wrong_answer":"Yes, it rains at the same time everywhere","correct_answer":"No, the months of the rains differ from place to place"}'::jsonb, 'The child has only lived through one county''s calendar.', 'Offer "Yes, it rains at the same time everywhere" next to the right answer and ask the question again in a new context.', 'Compare the class chart with a chart from another region read out by the teacher.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ACTIVITIES.M_SE_HARVEST_RAIN', 'SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ACTIVITIES', 'Thinks crops are harvested and dried in the rainy season.', '{"question":"When do farmers dry and store their maize?","wrong_answer":"In the rainy season","correct_answer":"In the dry season"}'::jsonb, 'The child knows rain makes crops grow and links rain with the whole farming year.', 'Offer "In the rainy season" next to the right answer and ask the question again in a new context.', 'Ask what happens to maize left out to dry in the rain: it rots.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ROAD.M_SE_UMBRELLA_SEEN', 'SOCI.G4.NATURA.SEASONS_IN_THE_COUNTY.SE_ROAD', 'Thinks holding an umbrella or wearing dark clothes in heavy rain makes a walker easy for drivers to see.', '{"question":"It is raining heavily in the evening. What helps drivers see a walker?","wrong_answer":"Dark clothes and an umbrella over the face","correct_answer":"Bright or reflective clothes and walking facing the traffic"}'::jsonb, 'The child thinks only about keeping dry, not about being seen.', 'Offer "Dark clothes and an umbrella over the face" next to the right answer and ask the question again in a new context.', 'In a dim room, hold up a dark cloth and a bright one: which do you see first?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_KINDS.M_HB_MUSEUM_MONUMENT', 'SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_KINDS', 'Mixes up a museum and a monument.', '{"question":"Which place keeps and shows old objects and records?","wrong_answer":"A monument","correct_answer":"A museum"}'::jsonb, 'The child treats all old built places as the same thing.', 'Offer "A monument" next to the right answer and ask the question again in a new context.', 'Ask: where do you go inside to see old tools and pictures, and what do you pass in a town square that remembers a person?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_KINDS.M_HB_NEW_IS_HISTORIC', 'SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_KINDS', 'Thinks any big or famous new building is a historic built environment.', '{"question":"Which is a historic built environment?","wrong_answer":"A new shopping mall","correct_answer":"An old fort that still stands"}'::jsonb, 'The child thinks big or famous means historic.', 'Offer "A new shopping mall" next to the right answer and ask the question again in a new context.', 'Ask for the date of each place and what it tells about the past.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_KINDS.M_HB_CENTRE_MARKET', 'SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_KINDS', 'Thinks a cultural centre is a market or a shop.', '{"question":"What is a cultural centre?","wrong_answer":"A place to buy and sell goods","correct_answer":"A place that shows the way of life of communities"}'::jsonb, 'The child links "centre" with a shopping centre.', 'Offer "A place to buy and sell goods" next to the right answer and ask the question again in a new context.', 'Ask what you might see and do at a cultural centre: dances, houses, crafts, food.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_IMPORTANCE.M_HB_OLD_USELESS', 'SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_IMPORTANCE', 'Thinks old places should be pulled down because they are old.', '{"question":"An old fort is crumbling. What should the county do?","wrong_answer":"Pull it down and build a new shop","correct_answer":"Repair and protect it because it tells our history"}'::jsonb, 'The child values only what is new.', 'Offer "Pull it down and build a new shop" next to the right answer and ask the question again in a new context.', 'Ask what a grandmother''s stories give that a new book does not, then link this to old places.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_IMPORTANCE.M_HB_MONEY_ONLY', 'SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_IMPORTANCE', 'Thinks historic places matter only for the money from visitors.', '{"question":"Why do we keep museums and monuments?","wrong_answer":"Only to earn money from visitors","correct_answer":"To learn about the past and keep our identity, and visitors also bring income"}'::jsonb, 'The child sees one reason where there are several.', 'Offer "Only to earn money from visitors" next to the right answer and ask the question again in a new context.', 'Brainstorm three reasons for keeping a place; mark which are about learning and which about income.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_KINDS.M_HB_RUINS_RUBBISH', 'SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_KINDS', 'Thinks ruins are broken rubbish and not a historic site because the buildings are not whole.', '{"question":"Gede has old broken walls with no roofs. Is it a historic built environment?","wrong_answer":"No, it is only broken stones","correct_answer":"Yes, it is ruins of an old town that tell us how people lived"}'::jsonb, 'The child judges a place by whether it looks good now.', 'Offer "No, it is only broken stones" next to the right answer and ask the question again in a new context.', 'Show a photo of Gede and a drawing of what the town looked like; ask what the walls tell us.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_IMPORTANCE.M_HB_ONLY_TOURISTS', 'SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_IMPORTANCE', 'Thinks historic places are only for foreign tourists, not for local people.', '{"question":"Who can learn from a museum in the county?","wrong_answer":"Only visitors from other countries","correct_answer":"Everyone: learners, families and visitors"}'::jsonb, 'The child has seen tourists at such places on television and not local families.', 'Offer "Only visitors from other countries" next to the right answer and ask the question again in a new context.', 'Plan a class visit or show a photo of a school group in a museum.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_IMPORTANCE.M_HB_WRITE_ON_WALLS', 'SOCI.G4.NATURA.HISTORIC_BUILT_ENVIRONME.HB_IMPORTANCE', 'Thinks writing names on an old wall or taking a stone home shows love for the place.', '{"question":"Which shows care for a historic site?","wrong_answer":"Writing your name on the wall to remember the visit","correct_answer":"Keeping it clean and leaving everything as you found it"}'::jsonb, 'The child copies what they have seen visitors do and thinks it is a way of remembering.', 'Offer "Writing your name on the wall to remember the visit" next to the right answer and ask the question again in a new context.', 'Ask what the wall would look like if every visitor wrote on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_WAYS.M_ID_SELF_SUFFICIENT', 'SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_WAYS', 'Thinks a family can make or grow everything it needs.', '{"question":"Can one family grow, make and do everything it needs?","wrong_answer":"Yes, if it works hard","correct_answer":"No, so people depend on each other"}'::jsonb, 'The child sees one family in the home, not the work of others behind each thing.', 'Offer "Yes, if it works hard" next to the right answer and ask the question again in a new context.', 'List what a family uses in one day and who made each thing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_WAYS.M_ID_ONE_WAY', 'SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_WAYS', 'Thinks only one side depends on the other (the shopkeeper does not need the farmer).', '{"question":"A farmer sells vegetables to a shopkeeper. Who needs the other?","wrong_answer":"Only the farmer needs the shopkeeper","correct_answer":"Both need each other"}'::jsonb, 'The child sees the farmer as the one with the problem.', 'Offer "Only the farmer needs the shopkeeper" next to the right answer and ask the question again in a new context.', 'Ask what the shopkeeper sells if no farmers sell to him, and what the farmer does if there is no shop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_WAYS.M_ID_SERVICE_MATCH', 'SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_WAYS', 'Matches a worker or place to the wrong service (a hospital for food, a church for medicine).', '{"question":"What does a hospital give people?","wrong_answer":"Food to eat","correct_answer":"Care for the sick"}'::jsonb, 'The child guesses from the building and not from what it does.', 'Offer "Food to eat" next to the right answer and ask the question again in a new context.', 'Make a matching chart of five places and what they give.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_BENEFITS.M_ID_WEAKNESS', 'SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_BENEFITS', 'Thinks needing other people is a weakness or a bad thing.', '{"question":"Is it bad to depend on other people?","wrong_answer":"Yes, strong people do things alone","correct_answer":"No, it lets everyone use their skills and gain more"}'::jsonb, 'The child equates depending on others with being unable.', 'Offer "Yes, strong people do things alone" next to the right answer and ask the question again in a new context.', 'Ask who made the school desk, who grew the lunch and who taught the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_BENEFITS.M_ID_MONEY_ONLY', 'SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_BENEFITS', 'Thinks the only benefit of trade or sharing is money.', '{"question":"What do people get when they depend on each other?","wrong_answer":"Only money","correct_answer":"Goods and services they cannot make and also friendship and income"}'::jsonb, 'The child links trade only to cash.', 'Offer "Only money" next to the right answer and ask the question again in a new context.', 'Ask what a neighbour who lends a tool gives that is not money.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_WAYS.M_ID_RICH_INDEPENDENT', 'SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_WAYS', 'Thinks a rich person does not depend on anyone because they can pay.', '{"question":"A rich trader has lots of money. Does she depend on other people?","wrong_answer":"No, money means she needs nobody","correct_answer":"Yes, she needs farmers, drivers, doctors and workers"}'::jsonb, 'The child sees money as the thing that meets needs, not the people money pays.', 'Offer "No, money means she needs nobody" next to the right answer and ask the question again in a new context.', 'Ask what she can buy if every farmer and shopkeeper stopped working.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_BENEFITS.M_ID_TOWN_ONLY', 'SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_BENEFITS', 'Thinks people depend on each other only in towns, and village families live alone.', '{"question":"Do people in a village depend on each other?","wrong_answer":"No, village families do everything alone","correct_answer":"Yes, they share work, trade at the market and help at weddings and funerals"}'::jsonb, 'The child pictures a village home growing its own food and misses the sharing.', 'Offer "No, village families do everything alone" next to the right answer and ask the question again in a new context.', 'List what a village family gets from others: the posho mill, the market, the clinic, help at harvest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_BENEFITS.M_ID_JOBS_NONE', 'SOCI.G4.PEOPLE.INTERDEPENDENCE_OF_PEOPL.ID_BENEFITS', 'Does not see that depending on each other creates jobs.', '{"question":"Farmers need lorries to take milk to the factory. What does this give the lorry driver?","wrong_answer":"Nothing, the farmer gains","correct_answer":"A job and an income"}'::jsonb, 'The child sees only the person who needs help gaining.', 'Offer "Nothing, the farmer gains" next to the right answer and ask the question again in a new context.', 'Act it out: the farmer pays the driver; who has money now?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.PEOPLE.POPULATION_DISTRIBUTION.PD_PATTERNS.M_PD_TOTAL', 'SOCI.G4.PEOPLE.POPULATION_DISTRIBUTION.PD_PATTERNS', 'Mixes up population distribution with the total number of people.', '{"question":"What does population distribution mean?","wrong_answer":"The total number of people in a county","correct_answer":"How people are spread over an area"}'::jsonb, 'The child links "population" with counting.', 'Offer "The total number of people in a county" next to the right answer and ask the question again in a new context.', 'Place twelve counters on a page: first all in one corner, then spread out; the total is the same.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.PEOPLE.POPULATION_DISTRIBUTION.PD_PATTERNS.M_PD_DENSE_BIG', 'SOCI.G4.PEOPLE.POPULATION_DISTRIBUTION.PD_PATTERNS', 'Thinks a dense area is a large area.', '{"question":"An area has many people living close together. Is it dense or sparse?","wrong_answer":"Sparse","correct_answer":"Dense"}'::jsonb, 'The child links dense with large size or fills the word with a different meaning.', 'Offer "Sparse" next to the right answer and ask the question again in a new context.', 'Compare ten learners in a small room and ten on a football pitch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.PEOPLE.POPULATION_DISTRIBUTION.PD_PATTERNS.M_PD_REASON_REVERSE', 'SOCI.G4.PEOPLE.POPULATION_DISTRIBUTION.PD_PATTERNS', 'Gives reasons the wrong way round (people crowd into very dry, steep or unsafe places).', '{"question":"Why do many people live near a river with good soil and rain?","wrong_answer":"Because there is no water there","correct_answer":"Because they get water, food and work there"}'::jsonb, 'The child does not link where people live with what the land gives.', 'Offer "Because there is no water there" next to the right answer and ask the question again in a new context.', 'Ask what the family needs each day and where they find it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.PEOPLE.POPULATION_DISTRIBUTION.PD_PATTERNS.M_PD_EVEN_SPREAD', 'SOCI.G4.PEOPLE.POPULATION_DISTRIBUTION.PD_PATTERNS', 'Thinks people are spread evenly over a county, the same number on every piece of land.', '{"question":"Is the number of people the same in every part of a county?","wrong_answer":"Yes, people spread out evenly","correct_answer":"No, some parts are crowded and others have few people"}'::jsonb, 'The child pictures the county map as one colour.', 'Offer "Yes, people spread out evenly" next to the right answer and ask the question again in a new context.', 'Drop beans on the map where the class thinks people live; the beans bunch up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.SOCIAL.ASPECTS_OF_TRADITIONAL_C.TC_ASPECTS.M_TC_MIX_ASPECT', 'SOCI.G4.SOCIAL.ASPECTS_OF_TRADITIONAL_C.TC_ASPECTS', 'Sorts an example under the wrong aspect (a drum under dressing, ugali under housing).', '{"question":"Under which aspect of culture is a kiondo (a sisal basket)?","wrong_answer":"Dressing","correct_answer":"Artefacts"}'::jsonb, 'The child sorts by the first thing that comes to mind.', 'Offer "Dressing" next to the right answer and ask the question again in a new context.', 'Make six boxes, one for each aspect, and sort a pile of picture cards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.SOCIAL.ASPECTS_OF_TRADITIONAL_C.TC_ASPECTS.M_TC_PAST_ONLY', 'SOCI.G4.SOCIAL.ASPECTS_OF_TRADITIONAL_C.TC_ASPECTS', 'Thinks traditional culture belongs only to the past or only to old people.', '{"question":"Is traditional culture still practised today?","wrong_answer":"No, it is finished","correct_answer":"Yes, many people still practise it"}'::jsonb, 'The child sees culture as something in a museum.', 'Offer "No, it is finished" next to the right answer and ask the question again in a new context.', 'Ask which dishes, songs and ceremonies the family still shares.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.SOCIAL.ASPECTS_OF_TRADITIONAL_C.TC_ASPECTS.M_TC_ONE_CULTURE', 'SOCI.G4.SOCIAL.ASPECTS_OF_TRADITIONAL_C.TC_ASPECTS', 'Thinks all communities in a county have the same traditions.', '{"question":"Do all the communities in a county have the same traditions?","wrong_answer":"Yes, they all do the same things","correct_answer":"No, each community has its own as well as shared ones"}'::jsonb, 'The child knows only the home community well.', 'Offer "Yes, they all do the same things" next to the right answer and ask the question again in a new context.', 'Ask each learner to name one dish, dance or dress from their own community.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.SOCIAL.ASPECTS_OF_TRADITIONAL_C.TC_ASPECTS.M_TC_BAD_OLD', 'SOCI.G4.SOCIAL.ASPECTS_OF_TRADITIONAL_C.TC_ASPECTS', 'Thinks traditional culture is backward and should all be dropped.', '{"question":"A learner says all traditional culture is backward. What is a good reply?","wrong_answer":"Yes, it should all be stopped","correct_answer":"No: much of it, like songs, food and respect for elders, is still good today"}'::jsonb, 'The child has heard harmful customs criticised and puts all culture with them.', 'Offer "Yes, it should all be stopped" next to the right answer and ask the question again in a new context.', 'List good parts of culture the class still enjoys: food, songs, games, respect for elders.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.SOCIAL.THE_SCHOOL.SC_VALUES.M_SC_VALUE_MIX', 'SOCI.G4.SOCIAL.THE_SCHOOL.SC_VALUES', 'Names the wrong value for a situation (calls handing in lost money respect, not honesty).', '{"question":"Wekesa finds a lost shilling coin and hands it to the teacher. Which value does he show?","wrong_answer":"Hard work","correct_answer":"Honesty"}'::jsonb, 'The child knows the words and does not tie them to actions.', 'Offer "Hard work" next to the right answer and ask the question again in a new context.', 'Make cards of the value words and match them to six short scenes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.SOCIAL.THE_SCHOOL.SC_VALUES.M_SC_RULES_ONLY', 'SOCI.G4.SOCIAL.THE_SCHOOL.SC_VALUES', 'Thinks values are the same as rules or punishments.', '{"question":"Which is a value of a school?","wrong_answer":"The cane","correct_answer":"Respect"}'::jsonb, 'The child links school with rules and punishments.', 'Offer "The cane" next to the right answer and ask the question again in a new context.', 'Ask the child what a value is: a good idea that guides us, even without a teacher watching.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.SOCIAL.THE_SCHOOL.SC_VALUES.M_SC_WATCHED_ONLY', 'SOCI.G4.SOCIAL.THE_SCHOOL.SC_VALUES', 'Thinks a value matters only when a teacher is watching.', '{"question":"Juma picks up litter when no teacher is near. Is he showing a value?","wrong_answer":"No, nobody saw it","correct_answer":"Yes, he shows responsibility and cleanliness"}'::jsonb, 'The child links values to praise or punishment from a teacher.', 'Offer "No, nobody saw it" next to the right answer and ask the question again in a new context.', 'Ask whether the compound is cleaner whether or not a teacher saw it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.SOCIAL.THE_SCHOOL.SC_VALUES.M_SC_MOTTO_VALUE', 'SOCI.G4.SOCIAL.THE_SCHOOL.SC_VALUES', 'Thinks the school motto is the same as a school value or a rule.', '{"question":"Our motto is \"Strive to excel\". Is the motto a school rule?","wrong_answer":"Yes, it is a rule we are punished for breaking","correct_answer":"No: a motto is a short saying that guides the school; values are qualities we show"}'::jsonb, 'Motto, values and rules are all written on the same notice board.', 'Offer "Yes, it is a rule we are punished for breaking" next to the right answer and ask the question again in a new context.', 'Read the notice board together and sort: motto, values, rules.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_RESOURCES_ACTIVITIES.M_EA_MADE_NATURAL', 'SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_RESOURCES_ACTIVITIES', 'Calls a thing made by people a natural resource (a building, a road).', '{"question":"Which is a natural resource?","wrong_answer":"A road","correct_answer":"A river"}'::jsonb, 'The child counts every useful thing as natural.', 'Offer "A road" next to the right answer and ask the question again in a new context.', 'Sort a list into things that were here before people and things people built.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_RESOURCES_ACTIVITIES.M_EA_NOT_ECONOMIC', 'SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_RESOURCES_ACTIVITIES', 'Calls play or rest an economic activity (or does not see farming as one).', '{"question":"Which is an economic activity?","wrong_answer":"Playing football after school","correct_answer":"Selling vegetables at the market"}'::jsonb, 'The child counts every kind of activity.', 'Offer "Playing football after school" next to the right answer and ask the question again in a new context.', 'Ask whether the activity gives food, goods or an income.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_RESOURCES_ACTIVITIES.M_EA_ACT_RESOURCE', 'SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_RESOURCES_ACTIVITIES', 'Matches an activity to the wrong resource (fishing for a forest, mining for water).', '{"question":"Which resource does fishing use?","wrong_answer":"Forests","correct_answer":"Lakes, rivers or the sea"}'::jsonb, 'The child guesses from the word and not from the product.', 'Offer "Forests" next to the right answer and ask the question again in a new context.', 'Ask: what does the activity bring in? Then ask where it comes from.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_IMPORTANCE.M_EA_RICH_ONLY', 'SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_IMPORTANCE', 'Thinks economic activities help only rich people.', '{"question":"Who gains from farming in a county?","wrong_answer":"Only rich people","correct_answer":"Farmers, workers, traders and everyone who eats"}'::jsonb, 'The child links activity to the wealth of the owner.', 'Offer "Only rich people" next to the right answer and ask the question again in a new context.', 'Trace a loaf of bread from the farm to the table and name the people who gain at each step.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_IMPORTANCE.M_EA_FOOD_ONLY', 'SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_IMPORTANCE', 'Thinks activities give only food, not jobs, income or raw materials.', '{"question":"Which is a reason that mining matters to a county?","wrong_answer":"It gives food","correct_answer":"It gives jobs, income and raw materials"}'::jsonb, 'The child gives the answer for farming to every activity.', 'Offer "It gives food" next to the right answer and ask the question again in a new context.', 'Make a table of five activities and what each gives.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_RESOURCES_ACTIVITIES.M_EA_RESOURCE_ACTIVITY_SAME', 'SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_RESOURCES_ACTIVITIES', 'Calls the activity a resource (says fishing is a resource and the lake is the activity).', '{"question":"In \"people fish in Lake Victoria\", which is the resource?","wrong_answer":"Fishing","correct_answer":"The lake and its fish"}'::jsonb, 'The two words are always taught together and the child does not hold the difference.', 'Offer "Fishing" next to the right answer and ask the question again in a new context.', 'Ask: which one can you touch and which one do people do?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_IMPORTANCE.M_EA_COUNTY_NOTHING', 'SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_IMPORTANCE', 'Thinks economic activities help only the family that does them and give the county nothing.', '{"question":"How does a busy market help the whole county?","wrong_answer":"It does not; only the traders gain","correct_answer":"Traders pay market fees that the county uses for services"}'::jsonb, 'The child sees only the person who earns.', 'Offer "It does not; only the traders gain" next to the right answer and ask the question again in a new context.', 'Show a market fee receipt and ask where the money goes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_IMPORTANCE.M_EA_ONE_ACTIVITY', 'SOCI.G4.RESOUR.ECONOMIC_ACTIVITIES_IN_T.EA_IMPORTANCE', 'Thinks a county should do only one economic activity, the one it is known for.', '{"question":"Mlima County is known for tea. Should its people do only tea farming?","wrong_answer":"Yes, only tea","correct_answer":"No: many activities, like dairy, trade and tourism, give more jobs and income"}'::jsonb, 'The child hears a county named by one crop and thinks it is the only one.', 'Offer "Yes, only tea" next to the right answer and ask the question again in a new context.', 'List three things people in a tea area also do for a living.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_KINDS.M_IN_RAW_PRODUCT', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_KINDS', 'Swaps the raw material and the product (thinks sugar is the raw material for sugarcane).', '{"question":"What is the raw material in a sugar factory?","wrong_answer":"Sugar","correct_answer":"Sugarcane"}'::jsonb, 'The child names the thing he or she knows best.', 'Offer "Sugar" next to the right answer and ask the question again in a new context.', 'Use pairs: before the factory and after the factory.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_KINDS.M_IN_SHOP_INDUSTRY', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_KINDS', 'Calls a shop or a farm an industry.', '{"question":"Which place is an industry?","wrong_answer":"A shop that sells sugar","correct_answer":"A factory that turns sugarcane into sugar"}'::jsonb, 'The child thinks any busy business is an industry.', 'Offer "A shop that sells sugar" next to the right answer and ask the question again in a new context.', 'Ask: does this place make something new from something else?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_BENEFITS.M_IN_OWNER_ONLY', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_BENEFITS', 'Thinks only the owner gains from an industry.', '{"question":"Who gains when a factory opens in a county?","wrong_answer":"Only the owner","correct_answer":"Workers, farmers, shoppers and the county"}'::jsonb, 'The child sees the owner as the only person involved.', 'Offer "Only the owner" next to the right answer and ask the question again in a new context.', 'List who works at a milk factory, who sells it the milk and who buys the milk.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_BENEFITS.M_IN_POLLUTION_BENEFIT', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_BENEFITS', 'Lists pollution or noise as a benefit.', '{"question":"Which is a benefit of an industry?","wrong_answer":"Dirty smoke from the chimney","correct_answer":"Jobs for people in the county"}'::jsonb, 'The child does not tell a benefit from a problem.', 'Offer "Dirty smoke from the chimney" next to the right answer and ask the question again in a new context.', 'Sort a list into "good for people" and "problem to solve".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_LOCATE.M_IN_ANYWHERE', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_LOCATE', 'Thinks an industry can be built anywhere with no reason.', '{"question":"Why is a sugar factory built near sugarcane farms?","wrong_answer":"Because there is no reason, any place does","correct_answer":"Because the heavy cane is cheap to carry a short way"}'::jsonb, 'The child does not link the place to the cost or ease of work.', 'Offer "Because there is no reason, any place does" next to the right answer and ask the question again in a new context.', 'Ask the child to carry a heavy bag a short way and a long way.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_LOCATE.M_IN_RAW_FAR', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_LOCATE', 'Places an industry far from its raw material (a milk factory far from dairy farms).', '{"question":"Where is the best place for a milk factory?","wrong_answer":"Far from any dairy farms","correct_answer":"Near the dairy farms, with good roads"}'::jsonb, 'The child thinks only about the buyer, not about milk that goes bad.', 'Offer "Far from any dairy farms" next to the right answer and ask the question again in a new context.', 'Ask what happens to fresh milk after a day in the sun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_KINDS.M_IN_HANDMADE_NOT', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_KINDS', 'Thinks only big factories with machines are industries, not a small jaggery mill or a basket-making group.', '{"question":"A women''s group makes baskets from sisal to sell. Is this an industry?","wrong_answer":"No, only big factories are industries","correct_answer":"Yes, a small industry that makes goods from a raw material"}'::jsonb, 'The word industry is shown with pictures of big factories.', 'Offer "No, only big factories are industries" next to the right answer and ask the question again in a new context.', 'Compare a big sugar factory and a jaggery mill: both turn sugarcane into a product.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_KINDS.M_IN_PRODUCT_RAW_TEA', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_KINDS', 'Names the factory by what it buys, not what it makes, so calls a tea factory a "leaf factory" and says it sells leaves.', '{"question":"A tea factory buys green tea leaves from farmers. What does it sell?","wrong_answer":"Green leaves","correct_answer":"Made tea, ready to drink"}'::jsonb, 'The child sees the leaves go in and assumes the same thing comes out.', 'Offer "Green leaves" next to the right answer and ask the question again in a new context.', 'Show green leaves and a packet of tea side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_BENEFITS.M_IN_FARMER_NO_GAIN', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_BENEFITS', 'Thinks a factory takes from farmers and gives them nothing.', '{"question":"How does a milk factory help dairy farmers?","wrong_answer":"It does not; it takes their milk","correct_answer":"It buys their milk, so they have a sure market and income"}'::jsonb, 'The child sees milk leaving the farm and not the payment coming back.', 'Offer "It does not; it takes their milk" next to the right answer and ask the question again in a new context.', 'Draw the milk going to the factory and the money going back to the farmer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_BENEFITS.M_IN_BENEFIT_HARM_SAME', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_BENEFITS', 'Lists a problem caused by an industry as a benefit (more lorries on the road, smoke).', '{"question":"Which is a benefit of a factory: jobs, smoke, noise?","wrong_answer":"Smoke, it shows the factory is busy","correct_answer":"Jobs"}'::jsonb, 'The child connects smoke and noise with a working factory and so with something good.', 'Offer "Smoke, it shows the factory is busy" next to the right answer and ask the question again in a new context.', 'Sort cards into "helps people" and "harms people".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_LOCATE.M_IN_NO_ROAD', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_LOCATE', 'Places a factory far from any road because land is cheaper there.', '{"question":"Where should a new milk factory go: next to the dairy farms by the main road, or on a far hill with no road?","wrong_answer":"On the far hill, land is cheap","correct_answer":"By the dairy farms and the main road"}'::jsonb, 'The child thinks only of the land, not of moving milk and workers.', 'Offer "On the far hill, land is cheap" next to the right answer and ask the question again in a new context.', 'Ask how lorries will bring milk to the far hill.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_LOCATE.M_IN_HOMES_INSIDE', 'SOCI.G4.RESOUR.INDUSTRIES_IN_THE_COUNTY.IN_LOCATE', 'Thinks a noisy factory is best built in the middle of homes so workers are close.', '{"question":"Where is the best place for a noisy, smoky factory?","wrong_answer":"In the middle of the houses","correct_answer":"Near the town but away from homes, with roads and water"}'::jsonb, 'The child thinks only about how far workers walk.', 'Offer "In the middle of the houses" next to the right answer and ask the question again in a new context.', 'Ask how families would sleep next to the noise and smoke.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_PROJECTS.M_EP_UNSUITABLE', 'SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_PROJECTS', 'Chooses a project that needs what the school does not have (fish ponds with no water).', '{"question":"A school has a dry field and no water tank. Which project suits it best?","wrong_answer":"Fish farming","correct_answer":"Keeping bees or planting drought-resistant trees"}'::jsonb, 'The child picks the most exciting project and does not check what is needed.', 'Offer "Fish farming" next to the right answer and ask the question again in a new context.', 'List what each project needs and tick what the school has.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_PROJECTS.M_EP_NO_PLAN', 'SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_PROJECTS', 'Thinks a project needs no plan, just start.', '{"question":"What should a school do before starting a project?","wrong_answer":"Start at once with no plan","correct_answer":"Make a plan of work, materials and who does what"}'::jsonb, 'The child links enterprise with action only.', 'Offer "Start at once with no plan" next to the right answer and ask the question again in a new context.', 'Plan a class lunch together: who brings what, and what does it cost?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_ETHICS.M_EP_PROFIT_SELF', 'SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_ETHICS', 'Thinks a leader can keep the money the project makes.', '{"question":"The class sold vegetables and made 500 shillings. What should the treasurer do?","wrong_answer":"Keep it for himself","correct_answer":"Record it and keep it safely for the project"}'::jsonb, 'The child sees money as belonging to whoever holds it.', 'Offer "Keep it for himself" next to the right answer and ask the question again in a new context.', 'Role play the treasurer with a record book and a locked box.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_ETHICS.M_EP_HIDE_LOSS', 'SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_ETHICS', 'Thinks a mistake or a loss should be hidden to avoid blame.', '{"question":"A group loses some money by mistake. What is right?","wrong_answer":"Hide it so no one is blamed","correct_answer":"Report it honestly and learn from it"}'::jsonb, 'The child fears blame.', 'Offer "Hide it so no one is blamed" next to the right answer and ask the question again in a new context.', 'Practise saying "we lost it, and here is what we will do".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_ETHICS.M_EP_ONE_PERSON', 'SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_ETHICS', 'Thinks one strong leader should do all the work or decide everything.', '{"question":"How should a project team decide?","wrong_answer":"The leader decides everything alone","correct_answer":"The team shares ideas and decides together"}'::jsonb, 'The child sees leadership as control.', 'Offer "The leader decides everything alone" next to the right answer and ask the question again in a new context.', 'Ask the team to decide where to keep the tools, then compare it with one person deciding.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_PROJECTS.M_EP_BIGGEST_BEST', 'SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_PROJECTS', 'Picks the biggest or most expensive project as the best one, whatever the school has.', '{"question":"A school has a small piece of land and little money. Which project fits best?","wrong_answer":"A large dairy farm","correct_answer":"A kitchen garden or a tree nursery"}'::jsonb, 'The child thinks a bigger project earns more and ignores what it needs.', 'Offer "A large dairy farm" next to the right answer and ask the question again in a new context.', 'List what each project needs and tick what the school has.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_PROJECTS.M_EP_NO_MARKET', 'SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_PROJECTS', 'Chooses a project without thinking who will buy what it makes.', '{"question":"Before starting to grow cabbages to sell, what should the class find out?","wrong_answer":"Nothing; just plant them","correct_answer":"Who will buy them, such as the school kitchen or parents"}'::jsonb, 'The child stops at making the product.', 'Offer "Nothing; just plant them" next to the right answer and ask the question again in a new context.', 'Ask what happens to fifty cabbages nobody buys.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_ETHICS.M_EP_NO_RECORD', 'SOCI.G4.RESOUR.ENTERPRISE_PROJECT_AT_SC.EP_ETHICS', 'Thinks money from a project need not be written down if everyone trusts each other.', '{"question":"The poultry project sold eggs for 600 shillings. Should the class write it down?","wrong_answer":"No, we trust each other","correct_answer":"Yes, in the record book, so everyone can see the money"}'::jsonb, 'The child thinks records are only for people who might steal.', 'Offer "No, we trust each other" next to the right answer and ask the question again in a new context.', 'Ask the class to remember last month''s sales without a book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.GOOD_CITIZENSHIP_IN_SCHO.GC_QUALITIES.M_GC_CLEVER_ONLY', 'SOCI.G4.CITIZE.GOOD_CITIZENSHIP_IN_SCHO.GC_QUALITIES', 'Thinks only learners with the top marks are good citizens.', '{"question":"Who is a good citizen in school?","wrong_answer":"Only the learner with the top marks","correct_answer":"Any learner who is respectful, honest and helpful"}'::jsonb, 'The child links a good learner with good marks.', 'Offer "Only the learner with the top marks" next to the right answer and ask the question again in a new context.', 'Ask what a learner can do for others even with low marks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.GOOD_CITIZENSHIP_IN_SCHO.GC_QUALITIES.M_GC_OBEY_ONLY', 'SOCI.G4.CITIZE.GOOD_CITIZENSHIP_IN_SCHO.GC_QUALITIES', 'Thinks a good citizen only keeps quiet and obeys, never speaks up.', '{"question":"Which learner is a good citizen?","wrong_answer":"The one who never speaks","correct_answer":"The one who keeps fair rules and helps others, and speaks up kindly when something is wrong"}'::jsonb, 'The child links good with silent.', 'Offer "The one who never speaks" next to the right answer and ask the question again in a new context.', 'Role play a learner who sees someone bullied: what is the good action?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.GOOD_CITIZENSHIP_IN_SCHO.GC_QUALITIES.M_GC_REPORT_BAD', 'SOCI.G4.CITIZE.GOOD_CITIZENSHIP_IN_SCHO.GC_QUALITIES', 'Thinks telling a teacher about bullying is wrong (telling tales).', '{"question":"You see a learner being bullied. What does a good citizen do?","wrong_answer":"Say nothing, because telling tales is wrong","correct_answer":"Tell a teacher and help the learner"}'::jsonb, 'The child confuses reporting harm with gossip.', 'Offer "Say nothing, because telling tales is wrong" next to the right answer and ask the question again in a new context.', 'Ask: is it gossip to tell a teacher that someone is being hurt?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.GOOD_CITIZENSHIP_IN_SCHO.GC_QUALITIES.M_GC_RICH_GOOD', 'SOCI.G4.CITIZE.GOOD_CITIZENSHIP_IN_SCHO.GC_QUALITIES', 'Thinks a learner with new shoes, a new bag or rich parents is a better citizen.', '{"question":"Who is a good citizen in school: a learner with a new bag, or a learner who helps others and keeps the class clean?","wrong_answer":"The learner with the new bag","correct_answer":"The learner who helps others and keeps the class clean"}'::jsonb, 'The child confuses being admired with being good.', 'Offer "The learner with the new bag" next to the right answer and ask the question again in a new context.', 'Ask what each learner does for the school.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.PEACE.PE_FACTORS.M_PE_NO_DISAGREE', 'SOCI.G4.CITIZE.PEACE.PE_FACTORS', 'Thinks peace means nobody ever disagrees.', '{"question":"What does peace mean in school?","wrong_answer":"Nobody ever disagrees","correct_answer":"Settling disagreements without hurting anyone"}'::jsonb, 'The child sees peace as quiet.', 'Offer "Nobody ever disagrees" next to the right answer and ask the question again in a new context.', 'Ask for a time when two friends disagreed and still stayed friends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.PEACE.PE_FACTORS.M_PE_THREAT', 'SOCI.G4.CITIZE.PEACE.PE_FACTORS', 'Thinks peace comes from fear and punishment.', '{"question":"What keeps a school peaceful?","wrong_answer":"Fear of strict punishment","correct_answer":"Respect, fairness and listening"}'::jsonb, 'The child links order with punishment.', 'Offer "Fear of strict punishment" next to the right answer and ask the question again in a new context.', 'Compare a class that is quiet for the cane and a class that is kind by choice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.PEACE.PE_FACTORS.M_PE_GOSSIP', 'SOCI.G4.CITIZE.PEACE.PE_FACTORS', 'Thinks spreading talk about others or taking sides helps peace.', '{"question":"Which action breaks peace?","wrong_answer":"Listening to both sides","correct_answer":"Spreading rumours about a classmate"}'::jsonb, 'The child does not see how talk hurts.', 'Offer "Listening to both sides" next to the right answer and ask the question again in a new context.', 'Pass a message along a line and watch it change.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.PEACE.PE_STRATEGIES.M_PE_FIGHT_BACK', 'SOCI.G4.CITIZE.PEACE.PE_STRATEGIES', 'Thinks hitting back or revenge settles a quarrel.', '{"question":"A classmate pushes you by mistake. What is the peaceful reply?","wrong_answer":"Push back harder","correct_answer":"Stay calm and say what happened"}'::jsonb, 'The child thinks strength ends a quarrel.', 'Offer "Push back harder" next to the right answer and ask the question again in a new context.', 'Role play both: what happens after a push back, and after a calm word?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.PEACE.PE_STRATEGIES.M_PE_AVOID', 'SOCI.G4.CITIZE.PEACE.PE_STRATEGIES', 'Thinks pretending the problem is not there is the best way, and never speaking again.', '{"question":"Two friends quarrelled. What is the best way to settle it?","wrong_answer":"Never speak to each other again","correct_answer":"Talk about it, say sorry and forgive"}'::jsonb, 'The child thinks silence ends a quarrel.', 'Offer "Never speak to each other again" next to the right answer and ask the question again in a new context.', 'Ask how the friendship feels after a week of silence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.PEACE.PE_STRATEGIES.M_PE_ORDER', 'SOCI.G4.CITIZE.PEACE.PE_STRATEGIES', 'Puts the steps of settling a quarrel in the wrong order (apologise before listening).', '{"question":"What comes first when settling a quarrel?","wrong_answer":"Shout until the other gives in","correct_answer":"Calm down and listen"}'::jsonb, 'The child does not think of steps.', 'Offer "Shout until the other gives in" next to the right answer and ask the question again in a new context.', 'Write the steps on cards and order them: calm, listen, talk, say sorry, forgive.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.PEACE.PE_FACTORS.M_PE_SAME_FRIENDS', 'SOCI.G4.CITIZE.PEACE.PE_FACTORS', 'Thinks peace means only playing with learners who are just like you.', '{"question":"Which helps peace in school: playing only with your own group, or welcoming learners who are different?","wrong_answer":"Playing only with your own group","correct_answer":"Welcoming learners who are different"}'::jsonb, 'The child feels safe with the familiar and thinks avoiding others prevents quarrels.', 'Offer "Playing only with your own group" next to the right answer and ask the question again in a new context.', 'Mix groups for a game and talk about what each learner brought.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.PEACE.PE_STRATEGIES.M_PE_ADULT_FIRST_ALWAYS', 'SOCI.G4.CITIZE.PEACE.PE_STRATEGIES', 'Thinks every small quarrel must go straight to the head teacher, never talked through first.', '{"question":"Two friends argue over whose turn it is on the swing. What should they try first?","wrong_answer":"Go straight to the head teacher","correct_answer":"Calm down, listen to each other and take turns"}'::jsonb, 'The child has learnt "tell a teacher" for serious things and uses it for everything.', 'Offer "Go straight to the head teacher" next to the right answer and ask the question again in a new context.', 'Act a small quarrel and solve it with talk; then act a fight and see when an adult is needed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILD_RIGHTS.CR_FORMS.M_CR_DISCIPLINE', 'SOCI.G4.CITIZE.CHILD_RIGHTS.CR_FORMS', 'Thinks beating a child is only discipline and never abuse.', '{"question":"A teacher beats a learner until he is hurt. Is this child abuse?","wrong_answer":"No, it is only discipline","correct_answer":"Yes, hurting a child is abuse"}'::jsonb, 'The child has seen beating treated as normal.', 'Offer "No, it is only discipline" next to the right answer and ask the question again in a new context.', 'Ask: does discipline teach with care or hurt? Discuss other ways, such as talking and fair consequences.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILD_RIGHTS.CR_FORMS.M_CR_WORK_OK', 'SOCI.G4.CITIZE.CHILD_RIGHTS.CR_FORMS', 'Thinks any work a child does is fine (or that all chores are child labour).', '{"question":"Which is child labour?","wrong_answer":"Washing a plate after supper","correct_answer":"Working all day in a quarry instead of going to school"}'::jsonb, 'The child does not tell light chores from harmful work.', 'Offer "Washing a plate after supper" next to the right answer and ask the question again in a new context.', 'Sort examples by: safe, short, does not stop school, does not harm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILD_RIGHTS.CR_FORMS.M_CR_ONLY_BEATING', 'SOCI.G4.CITIZE.CHILD_RIGHTS.CR_FORMS', 'Thinks only beating counts as child abuse.', '{"question":"Which of these is child abuse?","wrong_answer":"Only beating a child","correct_answer":"Forcing a girl to marry early"}'::jsonb, 'The child knows only the form seen most often.', 'Offer "Only beating a child" next to the right answer and ask the question again in a new context.', 'List six forms and ask: how does each harm the child?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILD_RIGHTS.CR_CAUSES.M_CR_CHILD_FAULT', 'SOCI.G4.CITIZE.CHILD_RIGHTS.CR_CAUSES', 'Thinks a child causes the abuse by bad behaviour.', '{"question":"Why was a child abused by an adult?","wrong_answer":"The child behaved badly","correct_answer":"The adult chose to harm the child"}'::jsonb, 'The child has heard "you made me do it".', 'Offer "The child behaved badly" next to the right answer and ask the question again in a new context.', 'Ask: can anything a child does make it right for an adult to hurt him or her?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILD_RIGHTS.CR_CAUSES.M_CR_TRADITION_OK', 'SOCI.G4.CITIZE.CHILD_RIGHTS.CR_CAUSES', 'Thinks a custom or tradition makes an abuse acceptable.', '{"question":"Some say a harmful custom is fine because it is old. What is right?","wrong_answer":"It is fine if it is a tradition","correct_answer":"A custom that harms a child must stop"}'::jsonb, 'The child respects elders and customs.', 'Offer "It is fine if it is a tradition" next to the right answer and ask the question again in a new context.', 'Discuss that culture changes, and that keeping children safe is also a tradition.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILD_RIGHTS.CR_EFFECTS.M_CR_NO_EFFECT', 'SOCI.G4.CITIZE.CHILD_RIGHTS.CR_EFFECTS', 'Thinks children forget abuse and are not changed by it.', '{"question":"What can child abuse do to a child?","wrong_answer":"Nothing, children forget","correct_answer":"It can hurt the body, cause fear and make the child leave school"}'::jsonb, 'The child thinks harm only shows on the body.', 'Offer "Nothing, children forget" next to the right answer and ask the question again in a new context.', 'List ways a bad experience at school changes how a learner feels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILD_RIGHTS.CR_EFFECTS.M_CR_SECRET', 'SOCI.G4.CITIZE.CHILD_RIGHTS.CR_EFFECTS', 'Thinks a hurt child or a friend should keep it secret.', '{"question":"A friend tells you an adult is hurting him. What should you do?","wrong_answer":"Keep it a secret","correct_answer":"Tell a trusted adult such as a teacher, or call Childline on 116"}'::jsonb, 'The child fears trouble or being a tell-tale.', 'Offer "Keep it a secret" next to the right answer and ask the question again in a new context.', 'Make a list of the adults who keep children safe and practise saying "I need to tell you something".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILD_RIGHTS.CR_FORMS.M_CR_STRANGER_ONLY', 'SOCI.G4.CITIZE.CHILD_RIGHTS.CR_FORMS', 'Thinks abuse is done only by strangers, never by people the child knows.', '{"question":"Can a child be abused by someone they know?","wrong_answer":"No, only strangers abuse children","correct_answer":"Yes, sometimes by someone they know, so the child must tell a trusted adult"}'::jsonb, 'The child is taught "stranger danger" and not that people known to them can harm.', 'Offer "No, only strangers abuse children" next to the right answer and ask the question again in a new context.', 'Say plainly that anyone who hurts a child is wrong, whoever they are, and the child should tell a trusted adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILD_RIGHTS.CR_CAUSES.M_CR_POOR_ONLY', 'SOCI.G4.CITIZE.CHILD_RIGHTS.CR_CAUSES', 'Thinks abuse happens only in poor families.', '{"question":"Does child abuse happen only in poor homes?","wrong_answer":"Yes, only in poor homes","correct_answer":"No, it can happen in any home"}'::jsonb, 'Poverty is taught as a cause, and the child takes it as the only one.', 'Offer "Yes, only in poor homes" next to the right answer and ask the question again in a new context.', 'List several causes together: drugs, harmful customs, greed, ignorance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILD_RIGHTS.CR_CAUSES.M_CR_ALCOHOL_EXCUSE', 'SOCI.G4.CITIZE.CHILD_RIGHTS.CR_CAUSES', 'Thinks an adult who was drunk is not to blame for hurting a child.', '{"question":"A drunk adult hit a child. Is the adult to blame?","wrong_answer":"No, it was the alcohol","correct_answer":"Yes, the adult is responsible, and drinking is a cause, not an excuse"}'::jsonb, 'The child hears adults excuse behaviour with "he was drunk".', 'Offer "No, it was the alcohol" next to the right answer and ask the question again in a new context.', 'Separate cause from blame: alcohol can lead to it, the adult still chose to drink and to hit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILD_RIGHTS.CR_EFFECTS.M_CR_PHYSICAL_ONLY_EFFECT', 'SOCI.G4.CITIZE.CHILD_RIGHTS.CR_EFFECTS', 'Thinks abuse only hurts the body and leaves no hurt once a wound heals.', '{"question":"A child''s bruise has healed. Can the child still be hurt by the abuse?","wrong_answer":"No, the bruise is gone","correct_answer":"Yes, the child can still feel fear, sadness or shame"}'::jsonb, 'The child can see bruises and cannot see feelings.', 'Offer "No, the bruise is gone" next to the right answer and ask the question again in a new context.', 'Talk about how a child might feel afraid or sad long after, using a story character.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILD_RIGHTS.CR_EFFECTS.M_CR_TELL_NOBODY_HELPS', 'SOCI.G4.CITIZE.CHILD_RIGHTS.CR_EFFECTS', 'Thinks telling an adult will only make things worse, so nothing can help.', '{"question":"A child is being hurt. Who can help?","wrong_answer":"Nobody; telling makes it worse","correct_answer":"A trusted adult such as a teacher, a parent or Childline on 116"}'::jsonb, 'The child may have been told to keep quiet or fears trouble.', 'Offer "Nobody; telling makes it worse" next to the right answer and ask the question again in a new context.', 'Name the helpers: a teacher, a parent, a chief, a nurse, Childline 116. Practise what to say.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_PROCESSES.M_DS_APPOINT', 'SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_PROCESSES', 'Thinks a leader chosen by the teacher is an election.', '{"question":"Which way of choosing a head prefect is democratic?","wrong_answer":"The teacher picks a favourite","correct_answer":"All learners vote"}'::jsonb, 'The child thinks any choosing is an election.', 'Offer "The teacher picks a favourite" next to the right answer and ask the question again in a new context.', 'Compare: who chose? how many people had a say?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_PROCESSES.M_DS_ORDER', 'SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_PROCESSES', 'Puts election steps in the wrong order (voting before the campaign).', '{"question":"Which comes first in a school election?","wrong_answer":"Counting the votes","correct_answer":"Nominating the candidates"}'::jsonb, 'The child remembers voting and counting only.', 'Offer "Counting the votes" next to the right answer and ask the question again in a new context.', 'Order the steps on cards: nominate, campaign, vote, count, announce.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_PROCESSES.M_DS_LOUD_WINS', 'SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_PROCESSES', 'Thinks the loudest or most popular learner wins by right.', '{"question":"How should a winner be decided?","wrong_answer":"The loudest learner wins","correct_answer":"By counting the votes of everyone"}'::jsonb, 'The child links winning with being strong.', 'Offer "The loudest learner wins" next to the right answer and ask the question again in a new context.', 'Hold a vote on a class song and count each hand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_BENEFITS.M_DS_MINORITY_IGNORED', 'SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_BENEFITS', 'Thinks those who lose a vote have no say and no value.', '{"question":"After a vote, what happens to the views of those who lost?","wrong_answer":"They are ignored","correct_answer":"They are still respected"}'::jsonb, 'The child sees the vote as a win or loss only.', 'Offer "They are ignored" next to the right answer and ask the question again in a new context.', 'After a class vote, ask the losers to say one idea that could still be used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_BENEFITS.M_DS_SLOW_BAD', 'SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_BENEFITS', 'Thinks democracy wastes time and one person should decide.', '{"question":"Why is democracy good for a school?","wrong_answer":"It is not, one person is quicker","correct_answer":"It gives everyone a voice and is fair"}'::jsonb, 'The child values speed over fairness.', 'Offer "It is not, one person is quicker" next to the right answer and ask the question again in a new context.', 'Compare a lunch menu chosen by one person with one chosen by the class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_PROCESSES.M_DS_OPEN_VOTE', 'SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_PROCESSES', 'Thinks voting by a show of hands in front of the candidates is the same as a secret ballot.', '{"question":"Why do we put votes in a closed box instead of raising hands?","wrong_answer":"There is no reason; both are the same","correct_answer":"So each learner can vote freely without fear"}'::jsonb, 'The child has used hands to vote for games and sees no difference.', 'Offer "There is no reason; both are the same" next to the right answer and ask the question again in a new context.', 'Ask whether a learner might vote differently if the big boy candidate is watching.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_BENEFITS.M_DS_WINNER_ALL', 'SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_BENEFITS', 'Thinks the winner of an election can do whatever they like.', '{"question":"A class prefect was elected. Can she make any rule she likes?","wrong_answer":"Yes, she won","correct_answer":"No: she must serve all learners and follow the school rules"}'::jsonb, 'The child thinks winning gives power, not duty.', 'Offer "Yes, she won" next to the right answer and ask the question again in a new context.', 'Ask what the prefect promised in her campaign and who she serves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_BENEFITS.M_DS_MAJORITY_ALWAYS_RIGHT', 'SOCI.G4.CITIZE.DEMOCRACY_IN_SCHOOL.DS_BENEFITS', 'Thinks whatever most learners vote for must be right, even if it hurts some learners.', '{"question":"Most of the class votes that one learner may not play in games. Is that fair?","wrong_answer":"Yes, most people voted for it","correct_answer":"No: a vote cannot take away another learner''s rights"}'::jsonb, 'The child has learnt the majority decides and stretches it to everything.', 'Offer "Yes, most people voted for it" next to the right answer and ask the question again in a new context.', 'Ask how the left-out learner feels and what the school rules say about everyone being included.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_COMPOSITION.M_CG_TEACHERS_ONLY', 'SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_COMPOSITION', 'Thinks the Children''s Government is made up of teachers.', '{"question":"Who forms the Children''s Government?","wrong_answer":"The teachers","correct_answer":"Learners elected by their classmates"}'::jsonb, 'The child thinks anything with "government" belongs to adults.', 'Offer "The teachers" next to the right answer and ask the question again in a new context.', 'Ask who voted for last year''s prefects.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_COMPOSITION.M_CG_APPOINTED', 'SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_COMPOSITION', 'Thinks the head teacher alone appoints all members.', '{"question":"How are members of the Children''s Government chosen?","wrong_answer":"The head teacher picks them all","correct_answer":"Learners vote for them"}'::jsonb, 'The child has not seen the election.', 'Offer "The head teacher picks them all" next to the right answer and ask the question again in a new context.', 'Walk through one election: nomination, campaign, vote.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_FUNCTIONS.M_CG_PUNISH', 'SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_FUNCTIONS', 'Thinks the Children''s Government can punish or cane learners.', '{"question":"Which is NOT a duty of the Children''s Government?","wrong_answer":"Caning learners who are late","correct_answer":"Passing learners'' worries to the teachers"}'::jsonb, 'The child links prefects with punishing.', 'Offer "Caning learners who are late" next to the right answer and ask the question again in a new context.', 'Ask what a prefect can do kindly: remind, report, help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_FUNCTIONS.M_CG_RUN_SCHOOL', 'SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_FUNCTIONS', 'Thinks it runs the school in place of the head teacher.', '{"question":"Who runs the school?","wrong_answer":"The Children''s Government","correct_answer":"The head teacher and the school management"}'::jsonb, 'The child thinks leaders have the power of the head.', 'Offer "The Children''s Government" next to the right answer and ask the question again in a new context.', 'Draw who reports to whom.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_COMPOSITION.M_CG_TOP_MARKS', 'SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_COMPOSITION', 'Thinks only the learners with the top marks can be in the Children''s Government.', '{"question":"Who can be elected to the Children''s Government?","wrong_answer":"Only the top learners in exams","correct_answer":"Any learner chosen by classmates for good conduct and leadership"}'::jsonb, 'The child sees prizes go to top learners and thinks every honour does.', 'Offer "Only the top learners in exams" next to the right answer and ask the question again in a new context.', 'Name a real member who leads well but is not top in class, if the school has one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_COMPOSITION.M_CG_FOREVER', 'SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_COMPOSITION', 'Thinks members stay in office until they leave the school.', '{"question":"How long does a Children''s Government member serve?","wrong_answer":"Until they leave the school","correct_answer":"For a set term, then a new election is held"}'::jsonb, 'The child has seen the same prefects for a long time.', 'Offer "Until they leave the school" next to the right answer and ask the question again in a new context.', 'Show the school''s election calendar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_FUNCTIONS.M_CG_FOR_TEACHERS', 'SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_FUNCTIONS', 'Thinks the Children''s Government only carries out teachers'' orders and does not speak for learners.', '{"question":"Learners want a covered place to eat lunch. What can the Children''s Government do?","wrong_answer":"Nothing; it only obeys teachers","correct_answer":"Take the learners'' request to the teachers and the head teacher"}'::jsonb, 'The child sees prefects passing on teachers'' orders.', 'Offer "Nothing; it only obeys teachers" next to the right answer and ask the question again in a new context.', 'Act out a minister taking a learners'' request to the head teacher.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_FUNCTIONS.M_CG_ONLY_ORDER', 'SOCI.G4.CITIZE.CHILDREN_S_GOVERNMENT_IN.CG_FUNCTIONS', 'Thinks its only job is keeping learners quiet.', '{"question":"Which is a job of the Children''s Government: organising a tree-planting day, or only keeping learners quiet?","wrong_answer":"Only keeping learners quiet","correct_answer":"Organising a tree-planting day"}'::jsonb, 'The child sees prefects most often when they are asking for silence.', 'Offer "Only keeping learners quiet" next to the right answer and ask the question again in a new context.', 'List what each minister does: environment, health, games, library.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_LEADERS.M_CL_POLITICIAN_ONLY', 'SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_LEADERS', 'Thinks leaders are only politicians.', '{"question":"Which is a leader in the community?","wrong_answer":"Only a politician","correct_answer":"A village elder, a religious leader or the chief"}'::jsonb, 'The child hears "leader" mainly in the news.', 'Offer "Only a politician" next to the right answer and ask the question again in a new context.', 'Ask who helps settle problems in the village.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_LEADERS.M_CL_DUTY_SWAP', 'SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_LEADERS', 'Gives a leader the wrong duty (the chief counsels in worship).', '{"question":"Who guides people in faith and prayer?","wrong_answer":"The chief","correct_answer":"A religious leader"}'::jsonb, 'The child knows the names but not the duties.', 'Offer "The chief" next to the right answer and ask the question again in a new context.', 'Match each leader to the duty on a chart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_QUALITIES.M_CL_STRONG_RICH', 'SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_QUALITIES', 'Thinks the strongest or richest person is the best leader.', '{"question":"Which person would make a good leader?","wrong_answer":"The richest person","correct_answer":"The honest person who listens"}'::jsonb, 'The child links power with leading.', 'Offer "The richest person" next to the right answer and ask the question again in a new context.', 'Ask which classmate you would follow and why.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_QUALITIES.M_CL_OWN_BENEFIT', 'SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_QUALITIES', 'Thinks leaders can use their post to benefit themselves.', '{"question":"A leader is given money for the village well. What should he do?","wrong_answer":"Keep some for himself","correct_answer":"Use it all for the well"}'::jsonb, 'The child has heard of leaders enriching themselves.', 'Offer "Keep some for himself" next to the right answer and ask the question again in a new context.', 'Discuss why trust matters to a leader.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_LEADERS.M_CL_ADULT_MEN_ONLY', 'SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_LEADERS', 'Thinks only men can be leaders in the community.', '{"question":"Can a woman be a community leader?","wrong_answer":"No, only men lead","correct_answer":"Yes, women lead as chiefs, elders, religious leaders and group chairpersons"}'::jsonb, 'The child has mostly seen men in leadership roles.', 'Offer "No, only men lead" next to the right answer and ask the question again in a new context.', 'Name women leaders in the community, such as a women''s group chairperson or a chief.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_LEADERS.M_CL_CHIEF_ELECTED', 'SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_LEADERS', 'Thinks the chief is elected by the villagers like an MCA.', '{"question":"How does a person become a chief?","wrong_answer":"The villagers vote for them","correct_answer":"The national government appoints them"}'::jsonb, 'The child knows other leaders are elected and assumes the chief is too.', 'Offer "The villagers vote for them" next to the right answer and ask the question again in a new context.', 'Compare: the MCA is voted for; the chief is appointed by the government.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_QUALITIES.M_CL_STRICT_BEST', 'SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_QUALITIES', 'Thinks a good leader is one who shouts and punishes the most.', '{"question":"Which leader is better: one who shouts at people, or one who listens and treats everyone fairly?","wrong_answer":"The one who shouts, people fear him","correct_answer":"The one who listens and is fair"}'::jsonb, 'The child links fear with control and control with good leading.', 'Offer "The one who shouts, people fear him" next to the right answer and ask the question again in a new context.', 'Ask which leader people would bring a problem to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_QUALITIES.M_CL_FAVOUR_OWN', 'SOCI.G4.CITIZE.COMMUNITY_LEADERSHIP.CL_QUALITIES', 'Thinks a good leader should help their own family and clan first.', '{"question":"A leader gives jobs only to his relatives. Is this good leadership?","wrong_answer":"Yes, family comes first","correct_answer":"No: a good leader treats everyone fairly"}'::jsonb, 'The child sees caring for family as good and does not see the unfairness to others.', 'Offer "Yes, family comes first" next to the right answer and ask the question again in a new context.', 'Ask how the other families feel when only relatives get jobs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_STRUCTURE.M_CO_NATIONAL', 'SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_STRUCTURE', 'Mixes county government with national government (puts the President and MPs in the county).', '{"question":"Who is in the county executive?","wrong_answer":"The President","correct_answer":"The Governor"}'::jsonb, 'The child hears the names on the news and puts them all together.', 'Offer "The President" next to the right answer and ask the question again in a new context.', 'Make two columns: national and county, and place each leader.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_STRUCTURE.M_CO_ASSEMBLY_MIX', 'SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_STRUCTURE', 'Puts the Governor in the county assembly or the MCAs in the executive.', '{"question":"Which one is a member of the county assembly?","wrong_answer":"The Governor","correct_answer":"A Member of the County Assembly (MCA)"}'::jsonb, 'The child does not tell the two parts apart.', 'Offer "The Governor" next to the right answer and ask the question again in a new context.', 'Draw two boxes: executive, assembly; place each person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_GOVERNOR.M_CO_GOV_LAWS', 'SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_GOVERNOR', 'Thinks the Governor makes the county laws.', '{"question":"Who makes the county laws?","wrong_answer":"The Governor","correct_answer":"The county assembly"}'::jsonb, 'The child thinks the head makes all rules.', 'Offer "The Governor" next to the right answer and ask the question again in a new context.', 'Ask: who makes the rules at school and who sees they are followed?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_GOVERNOR.M_CO_GOV_PRESIDENT', 'SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_GOVERNOR', 'Thinks the Governor is the head of the whole country.', '{"question":"The Governor is head of which?","wrong_answer":"The whole country","correct_answer":"The county"}'::jsonb, 'The child has the Governor and the President confused.', 'Offer "The whole country" next to the right answer and ask the question again in a new context.', 'Place the Governor and the President on a map of Kenya: which area does each lead?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_MCA.M_CO_MCA_ENFORCES', 'SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_MCA', 'Thinks the MCA carries out county work, building roads and running hospitals himself.', '{"question":"What does an MCA do?","wrong_answer":"Builds the roads himself","correct_answer":"Makes county laws and approves the budget"}'::jsonb, 'The child links leaders with doing the work.', 'Offer "Builds the roads himself" next to the right answer and ask the question again in a new context.', 'Ask who writes the plan and who builds the road.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_MCA.M_CO_MCA_WHOLE', 'SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_MCA', 'Thinks an MCA speaks for the whole country or the whole county.', '{"question":"Whom does an MCA represent?","wrong_answer":"The whole country","correct_answer":"The people of his or her ward"}'::jsonb, 'The child mixes up an MCA and an MP.', 'Offer "The whole country" next to the right answer and ask the question again in a new context.', 'Mark a ward on a sketch and name the MCA.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_STRUCTURE.M_CO_TWO_ARMS', 'SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_STRUCTURE', 'Thinks the county government is one person, the Governor.', '{"question":"Is the county government only the Governor?","wrong_answer":"Yes, the Governor is the county government","correct_answer":"No: it is the county executive and the county assembly"}'::jsonb, 'The Governor is the face of the county on news and posters.', 'Offer "Yes, the Governor is the county government" next to the right answer and ask the question again in a new context.', 'Draw the two boxes and fill them with all the people in each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_STRUCTURE.M_CO_SPEAKER_EXECUTIVE', 'SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_STRUCTURE', 'Puts the Speaker of the County Assembly in the county executive.', '{"question":"Is the Speaker of the County Assembly part of the county executive?","wrong_answer":"Yes, with the Governor","correct_answer":"No, the Speaker leads the meetings of the county assembly"}'::jsonb, 'Both sound like senior offices, so the child puts them together.', 'Offer "Yes, with the Governor" next to the right answer and ask the question again in a new context.', 'Put the Speaker''s card in the assembly box and say what the Speaker does there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_GOVERNOR.M_CO_GOV_FOREVER', 'SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_GOVERNOR', 'Thinks a Governor stays in office for life.', '{"question":"How long is a Governor''s term?","wrong_answer":"For life","correct_answer":"Five years, then there is an election"}'::jsonb, 'The child does not connect leaders with terms and elections.', 'Offer "For life" next to the right answer and ask the question again in a new context.', 'Show the general election cycle: every five years.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_GOVERNOR.M_CO_GOV_APPOINTED', 'SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_GOVERNOR', 'Thinks the President appoints the Governor.', '{"question":"Who chooses the Governor of a county?","wrong_answer":"The President","correct_answer":"The voters of the county, in an election"}'::jsonb, 'The child thinks every senior office is filled by the President.', 'Offer "The President" next to the right answer and ask the question again in a new context.', 'Ask who votes in the county at a general election.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_MCA.M_CO_MCA_APPOINTED', 'SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_MCA', 'Thinks MCAs are chosen by the Governor.', '{"question":"Who chooses the Member of the County Assembly for a ward?","wrong_answer":"The Governor","correct_answer":"The voters of the ward"}'::jsonb, 'The child thinks the Governor, as county head, picks everyone below.', 'Offer "The Governor" next to the right answer and ask the question again in a new context.', 'Name what is on the ballot at a general election, including the MCA.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_MCA.M_CO_MCA_BUDGET_NONE', 'SOCI.G4.CITIZE.THE_COUNTY_GOVERNMENTS_I.CO_MCA', 'Thinks the Governor alone decides how the county spends money, with no role for the assembly.', '{"question":"Who approves the county budget?","wrong_answer":"The Governor alone","correct_answer":"The county assembly, made up of MCAs"}'::jsonb, 'The child sees the Governor as the one who spends.', 'Offer "The Governor alone" next to the right answer and ask the question again in a new context.', 'Act a budget: the executive proposes, the MCAs debate and vote.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
